package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var writes = map[string]bool{"WriteFile": true, "OpenFile": true, "Create": true, "CreateTemp": true, "Rename": true, "Symlink": true, "Link": true, "Truncate": true}

func main() {
	var out []string
	for _, root := range []string{"internal", "cmd", "plugin"} {
		filepath.Walk(root, func(p string, i os.FileInfo, e error) error {
			if e != nil || i.IsDir() || !strings.HasSuffix(p, ".go") || strings.HasSuffix(p, "_test.go") {
				return nil
			}
			fs := token.NewFileSet()
			f, err := parser.ParseFile(fs, p, nil, 0)
			if err != nil {
				return nil
			}
			for _, d := range f.Decls {
				fd, ok := d.(*ast.FuncDecl)
				if !ok || fd.Body == nil {
					continue
				}
				found := map[string]bool{}
				ast.Inspect(fd.Body, func(n ast.Node) bool {
					c, ok := n.(*ast.CallExpr)
					if !ok {
						return true
					}
					if s, ok := c.Fun.(*ast.SelectorExpr); ok {
						if x, ok := s.X.(*ast.Ident); ok && x.Name == "os" && writes[s.Sel.Name] {
							found[s.Sel.Name] = true
						}
					}
					return true
				})
				if len(found) > 0 {
					name := fd.Name.Name
					if fd.Recv != nil {
						t := fd.Recv.List[0].Type
						if st, ok := t.(*ast.StarExpr); ok {
							t = st.X
						}
						name = t.(*ast.Ident).Name + "." + name
					}
					var ks []string
					for k := range found {
						ks = append(ks, k)
					}
					sort.Strings(ks)
					out = append(out, fmt.Sprintf("%s\t%s\t%v", filepath.ToSlash(filepath.Dir(p)), name, ks))
				}
			}
			return nil
