	} else {
		data, err = redactYAMLDoc(r, data)
	}
	if err != nil {
		return fmt.Errorf("redacting %s: %w", src, err)
	}
	return writeSyncedFile(dst, data)
}

// writeSyncedFile creates path at 0o600 with data, fsynced.
func writeSyncedFile(path string, data []byte) error {
	out, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
	if err != nil {
		return fmt.Errorf("creating %s: %w", path, err)
	}
	if _, err := out.Write(data); err != nil {
		_ = out.Close()
		return fmt.Errorf("writing %s: %w", path, err)
	}
	if err := out.Sync(); err != nil {
		_ = out.Close()
		return fmt.Errorf("syncing %s: %w", path, err)
	}
	// Check Close() explicitly: a failed close after a successful
	// Sync would otherwise be silently dropped by the deferred
	// pattern, and the migration would report success on a file
	// that's not fully committed to disk (Copilot on PR #328).
	if err := out.Close(); err != nil {
		return fmt.Errorf("closing %s: %w", path, err)
	}
	return nil
}

// redactYAMLDoc re-encodes a YAML document with every string scalar
// passed through r.Content. Keys, numbers, booleans and structure are
// untouched. An empty document stays empty.
func redactYAMLDoc(r PathRedactor, data []byte) ([]byte, error) {
	if len(bytes.TrimSpace(data)) == 0 {
		return data, nil
	}
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return nil, fmt.Errorf("parsing yaml: %w", err)
	}
	var walk func(n *yaml.Node, isKey bool)
	walk = func(n *yaml.Node, isKey bool) {
		switch n.Kind {
		case yaml.ScalarNode:
			if !isKey && n.Tag == "!!str" {
				n.Value = r.Content(n.Value)
			}
		case yaml.MappingNode:
			for i, c := range n.Content {
				walk(c, i%2 == 0)
			}
		default:
			for _, c := range n.Content {
				walk(c, false)
			}
		}
	}
	walk(&doc, false)
	out, err := yaml.Marshal(&doc)
	if err != nil {
		return nil, fmt.Errorf("encoding yaml: %w", err)
	}
	return out, nil
}

// redactJSONLines re-encodes a JSONL body line by line with every string
// value passed through r.Content. Blank lines are dropped.
func redactJSONLines(r PathRedactor, data []byte) ([]byte, error) {
	var out bytes.Buffer
	for i, line := range bytes.Split(data, []byte("\\n")) {
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}
		dec := json.NewDecoder(bytes.NewReader(line))
		dec.UseNumber()
		var v any
		if err := dec.Decode(&v); err != nil {
			return nil, fmt.Errorf("line %d: parsing json: %w", i+1, err)
		}
		b, err := json.Marshal(RedactJSON(r, v))
		if err != nil {
			return nil, fmt.Errorf("line %d: encoding json: %w", i+1, err)
		}
		out.Write(b)
		out.WriteByte('\\n')
	}
	return out.Bytes(), nil
}

// RedactJSON returns v (a decoded JSON value) with every string passed
// through r.Content and every string under a credential-named key
// replaced whole.
func RedactJSON(r PathRedactor, v any) any {
	return redact.Record(v, r.Content)
}

