package mission

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// This file is the coverage invariant for ethos-3e3f: every function that
// writes a file in a package that can reach a git-tracked tree under
// .punt-labs/ethos/ is either registered as passing its content through
// the shared redactor (internal/redact, via RedactRecord and friends) or
// registered as exempt with a stated reason. A new writer that is in
// neither list fails the test.
//
// What the test checks, and what it does not. It discovers writers
// syntactically: a function is a writer if it calls an os file-creating
// primitive, or calls a registered sink (a helper that writes bytes its
// caller hands it). It then requires each writer to be registered, and
// each "redacts" entry to contain calls to its named redactor entry
// points. It does not prove that every byte reaching a sink came through
// the redactor; the per-writer tests in store_redact_test.go,
// migrate_redact_test.go and cmd/ethos/redact_test.go do that by grepping
// the bytes on disk. This test is what makes "a new writer was added and
// nobody routed it through the redactor" a build failure instead of a
// review hope.

type writerClass int

const (
	// classRedacts: the function must call every identifier in calls.
	// It need not itself be a writer: a checkpoint such as buildAuditEntry
	// is registered so the chain from the writer to the redactor is
	// asserted at each link.
	classRedacts writerClass = iota
	// classSink: writes bytes its caller hands it. Every caller is
	// discovered as a writer and must be registered.
	classSink
	// classDownstream: receives content already redacted by the function
	// named in via, which must be its only caller and must itself be
	// registered classRedacts.
	classDownstream
	// classExempt: writes nothing that reaches a tracked mission or
	// audit record. reason says why.
	classExempt
	// classGap: a known leak, in a file outside the write set of the
	// mission that introduced this test. Logged on every run; delete the
	// entry when the writer is fixed.
	classGap
)

type writerEntry struct {
	class  writerClass
	calls  []string
	via    string
	reason string
}

func redacts(calls ...string) writerEntry { return writerEntry{class: classRedacts, calls: calls} }
func sink(reason string) writerEntry      { return writerEntry{class: classSink, reason: reason} }
func downstream(via, reason string) writerEntry {
	return writerEntry{class: classDownstream, via: via, reason: reason}
}
func exempt(reason string) writerEntry { return writerEntry{class: classExempt, reason: reason} }
func gap(reason string) writerEntry    { return writerEntry{class: classGap, reason: reason} }

const (
	reasonLock     = "lock file; carries no content"
	reasonCounter  = "ID counter in the global untracked tree; a number, no free text"
	reasonGlobal   = "global untracked tree (~/.punt-labs/ethos); never committed"
	reasonRollback = "rollback rewrite of bytes read back from the same file, which were redacted when first written"
)

// writerRegistry is keyed "<dir>.<Func>" or "<dir>.<Type>.<Method>", dir
// being slash-separated and relative to the repository root.
var writerRegistry = map[string]writerEntry{
	// internal/mission: records.
	"internal/mission.Store.writeContract":         redacts("RedactRecord"),
