}

// scanFuncs parses sources (path relative to the repo root -> content)
// and returns every function keyed "<dir>.<Func>" or "<dir>.<Type>.<Method>".
func scanFuncs(t *testing.T, sources map[string]string) map[string]*funcInfo {
	t.Helper()
	out := map[string]*funcInfo{}
	fset := token.NewFileSet()
	for path, src := range sources {
		f, err := parser.ParseFile(fset, path, src, 0)
		require.NoError(t, err, path)
		dir := filepath.ToSlash(filepath.Dir(path))
		for _, d := range f.Decls {
			fd, ok := d.(*ast.FuncDecl)
			if !ok || fd.Body == nil {
				continue
			}
			name := fd.Name.Name
			if fd.Recv != nil && len(fd.Recv.List) > 0 {
				name = recvName(fd.Recv.List[0].Type) + "." + name
			}
			fi := &funcInfo{key: dir + "." + name, callees: map[string]bool{}}
			ast.Inspect(fd.Body, func(n ast.Node) bool {
				c, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				switch fn := c.Fun.(type) {
				case *ast.Ident:
					fi.callees[fn.Name] = true
				case *ast.SelectorExpr:
					fi.callees[fn.Sel.Name] = true
					if x, ok := fn.X.(*ast.Ident); ok && x.Name == "os" && osWritePrims[fn.Sel.Name] {
						fi.prims = true
					}
				}
				return true
			})
			out[fi.key] = fi
		}
	}
	return out
}

func recvName(e ast.Expr) string {
	switch x := e.(type) {
	case *ast.StarExpr:
		return recvName(x.X)
	case *ast.Ident:
		return x.Name
	case *ast.IndexExpr:
		return recvName(x.X)
	}
	return "?"
}

func bareName(key string) string {
	if i := strings.LastIndex(key, "."); i >= 0 {
		return key[i+1:]
	}
	return key
}

func keyDir(key string) string {
	// "<dir>.<Func>" or "<dir>.<Type>.<Method>": dir ends before the first
	// '.' that follows the last '/'.
	slash := strings.LastIndex(key, "/")
	dot := strings.Index(key[slash+1:], ".")
	return key[:slash+1+dot]
}

// checkWriters returns one message per violation of the coverage
// invariant over funcs.
func checkWriters(funcs map[string]*funcInfo, registry map[string]writerEntry, exemptPkgs map[string]string) []string {
	var bad []string

	sinks := map[string]bool{}
	for k, e := range registry {
		if e.class == classSink {
			sinks[bareName(k)] = true
		}
	}

	writers := map[string]bool{}
	for k, fi := range funcs {
		if _, ok := exemptPkgs[keyDir(k)]; ok {
			continue
		}
		if fi.prims {
			writers[k] = true
			continue
		}
		for c := range fi.callees {
			if sinks[c] {
				writers[k] = true
			}
		}
	}

	for k := range writers {
		if _, ok := registry[k]; !ok {
			bad = append(bad, fmt.Sprintf(
				"unregistered writer %s: route its content through redact.Record (mission.RedactRecord) and register it in writerRegistry, or register it exempt with a reason", k))
		}
	}

	for k, e := range registry {
		fi, exists := funcs[k]
		if !exists {
			bad = append(bad, fmt.Sprintf("stale registry entry %s: no such function", k))
			continue
		}
		if e.class != classRedacts && !writers[k] {
			bad = append(bad, fmt.Sprintf("stale registry entry %s: no longer writes a file or calls a sink", k))
		}
		if e.class != classRedacts && strings.TrimSpace(e.reason) == "" {
			bad = append(bad, fmt.Sprintf("registry entry %s has no reason", k))
		}
		switch e.class {
		case classRedacts:
			for _, c := range e.calls {
				if !fi.callees[c] {
					bad = append(bad, fmt.Sprintf("%s is registered as redacting but does not call %s", k, c))
				}
			}
		case classDownstream:
			via := keyDir(k) + "." + e.via
			if v, ok := registry[via]; !ok || v.class != classRedacts {
				bad = append(bad, fmt.Sprintf("%s is downstream of %s, which is not registered as redacting", k, via))
			}
			var callers []string
			for ck, cfi := range funcs {
				if cfi.callees[bareName(k)] {
					callers = append(callers, ck)
				}
			}
			sort.Strings(callers)
			if len(callers) != 1 || callers[0] != via {
				bad = append(bad, fmt.Sprintf("%s must have %s as its only caller, has %v", k, via, callers))
			}
		}
	}
	sort.Strings(bad)
	return bad
}

// loadSources reads every non-test .go file under the packages that can
// write into a tracked tree.
func loadSources(t *testing.T, root string) map[string]string {
	t.Helper()
	out := map[string]string{}
	for _, top := range []string{"cmd", "internal", "plugin"} {
		err := filepath.WalkDir(filepath.Join(root, top), func(p string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !strings.HasSuffix(p, ".go") || strings.HasSuffix(p, "_test.go") {
				return nil
			}
			b, rerr := os.ReadFile(p)
			if rerr != nil {
				return rerr
			}
			rel, rerr := filepath.Rel(root, p)
			if rerr != nil {
				return rerr
			}
			out[filepath.ToSlash(rel)] = string(b)
			return nil
		})
		require.NoError(t, err)
	}
	return out
}

// TestTrackedWritersAreRedacted replaces the claim that used to sit in
// PathRedactor's doc comment ("every artifact ethos writes into a
// git-tracked tree passes through one of these") with a check.
func TestTrackedWritersAreRedacted(t *testing.T) {
	funcs := scanFuncs(t, loadSources(t, filepath.Join("..", "..")))
	require.Greater(t, len(funcs), 500, "scan found implausibly few functions; the walk is broken")

	assert.Empty(t, checkWriters(funcs, writerRegistry, exemptPackages))

	var gaps []string
	for k, e := range writerRegistry {
		if e.class == classGap {
			gaps = append(gaps, k+": "+e.reason)
		}
	}
	sort.Strings(gaps)
	for _, g := range gaps {
		t.Logf("KNOWN GAP %s", g)
	}
}

// TestCheckWriters_Mutants proves the checker fails when it should: a new
// unregistered writer, a registered redactor whose call was removed, a
// stale entry, an unregistered caller of a sink, and a downstream entry
// with a second caller.
func TestCheckWriters_Mutants(t *testing.T) {
	const base = `package p
import "os"
func redactIt(s string) string { return s }
func WriteRecord(b []byte) error { return os.WriteFile("x", redactIt(string(b)), 0o600) }
func sinkFn(b []byte) error { return os.WriteFile("x", b, 0o600) }
func viaSink(b []byte) error { return sinkFn(b) }
func up(b []byte) error { return viaSink(b) }
func Lock() error { _, err := os.OpenFile("l", 0, 0); return err }
`
	registry := func() map[string]writerEntry {
		return map[string]writerEntry{
			"internal/p.WriteRecord": redacts("redactIt"),
			"internal/p.sinkFn":      sink("test sink"),
			"internal/p.viaSink":     redacts("redactIt"),
			"internal/p.Lock":        exempt("lock"),
		}
	}
	run := func(src string, reg map[string]writerEntry) []string {
		return checkWriters(scanFuncs(t, map[string]string{"internal/p/p.go": src}), reg, nil)
	}

	t.Run("baseline has only the redactIt-less viaSink complaint", func(t *testing.T) {
		got := run(base, registry())
		assert.Equal(t, []string{
			"internal/p.viaSink is registered as redacting but does not call redactIt",
		}, got)
	})

	good := strings.Replace(base, "return sinkFn(b) }", "return sinkFn([]byte(redactIt(string(b)))) }", 1)

	t.Run("fully registered passes", func(t *testing.T) {
		assert.Empty(t, run(good, registry()))
	})

	t.Run("a new unredacted writer fails", func(t *testing.T) {
		src := good + "\nfunc Leak(b []byte) error { return os.WriteFile(\"y\", b, 0o600) }\n"
		got := run(src, registry())
		require.Len(t, got, 1)
		assert.Contains(t, got[0], "unregistered writer internal/p.Leak")
	})

	t.Run("a new caller of a sink fails", func(t *testing.T) {
		src := good + "\nfunc Leak2(b []byte) error { return sinkFn(b) }\n"
		got := run(src, registry())
		require.Len(t, got, 1)
		assert.Contains(t, got[0], "unregistered writer internal/p.Leak2")
	})

	t.Run("removing the redactor call fails", func(t *testing.T) {
		src := strings.Replace(good, `redactIt(string(b)), 0o600) }`, `b, 0o600) }`, 1)
		got := run(src, registry())
		require.Len(t, got, 1)
		assert.Contains(t, got[0], "WriteRecord is registered as redacting but does not call redactIt")
	})

	t.Run("a stale entry fails", func(t *testing.T) {
		reg := registry()
		reg["internal/p.Gone"] = exempt("was a lock")
		got := run(good, reg)
		require.Len(t, got, 1)
		assert.Contains(t, got[0], "stale registry entry internal/p.Gone")
	})

	t.Run("an exempt entry that no longer writes fails", func(t *testing.T) {
		src := strings.Replace(good, `_, err := os.OpenFile("l", 0, 0); return err`, `return nil`, 1)
		got := run(src, registry())
		require.Len(t, got, 1)
		assert.Contains(t, got[0], "no longer writes")
	})

	t.Run("a reasonless exemption fails", func(t *testing.T) {
		reg := registry()
		reg["internal/p.Lock"] = exempt("")
		got := run(good, reg)
		require.Len(t, got, 1)
		assert.Contains(t, got[0], "has no reason")
	})

	t.Run("downstream needs a single registered caller", func(t *testing.T) {
		reg := registry()
		reg["internal/p.sinkFn"] = downstream("viaSink", "only viaSink calls it")
		assert.Len(t, run(good, reg), 1, "WriteRecord is a registered-redacts writer and not a caller, but viaSink must be")
		src := good + "\nfunc Other(b []byte) { _ = sinkFn(b) }\n"
		got := run(src, reg)
		joined := strings.Join(got, "\n")
		assert.Contains(t, joined, "must have internal/p.viaSink as its only caller")
	})

	t.Run("an exempt package is skipped", func(t *testing.T) {
		got := checkWriters(
			scanFuncs(t, map[string]string{"internal/q/q.go": "package q\nimport \"os\"\nfunc F() { os.WriteFile(\"x\", nil, 0) }\n"}),
			nil, map[string]string{"internal/q": "config"})
		assert.Empty(t, got)
	})
}

