package mission

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"sort"
	"strings"

	"github.com/punt-labs/ethos/v4/internal/redact"
)

// TrackedRecordFiles returns the repo-relative, slash-separated paths git
// tracks under .punt-labs/ethos. It is the file list ScrubFiles is meant
// to be given: scrubbing only tracked files leaves the live zone and any
// in-flight mission untouched.
func TrackedRecordFiles(repoRoot string) ([]string, error) {
	out, err := exec.Command("git", "-C", repoRoot, "ls-files", "-z", "--", ".punt-labs/ethos").Output()
	if err != nil {
		return nil, fmt.Errorf("listing tracked files in %s: %w", repoRoot, err)
	}
	var rels []string
	for _, p := range bytes.Split(out, []byte{0}) {
		if len(p) > 0 {
			rels = append(rels, string(p))
		}
	}
	return rels, nil
}

// scrubMode says which passes a file gets.
type scrubMode int

const (
	scrubSkip scrubMode = iota
	// scrubFull is a mission record: paths, addresses, credentials.
	scrubFull
	// scrubHome is sealed audit history. Only home paths are rewritten:
	// addresses there are commit trailers and bot addresses, and the
	// lines are history.
	scrubHome
)

// scrubModeFor classifies a repo-relative path. Anything outside the
// mission tree, the trace log and the session audit tree is skipped, so
// the identity graph is never touched; so is the machine-local zone and
// any temp or lock file.
func scrubModeFor(rel string) scrubMode {
	rel = path.Clean(rel)
	base := path.Base(rel)
	for _, seg := range strings.Split(rel, "/") {
		if seg == "local" {
			return scrubSkip
		}
	}
	ext := path.Ext(base)
	switch {
	case rel == ".punt-labs/ethos/missions.jsonl":
		return scrubFull
	case strings.HasPrefix(rel, ".punt-labs/ethos/missions/"):
		if ext == ".yaml" || ext == ".jsonl" || ext == ".md" {
			return scrubFull
		}
	case strings.HasPrefix(rel, ".punt-labs/ethos/sessions/"):
		if ext == ".yaml" || ext == ".jsonl" || ext == ".md" {
			return scrubHome
		}
	}
	return scrubSkip
}

// ScrubFiles runs the shared redactor over already-written tracked
// records, the forward fix for files an older ethos wrote unredacted
// (operator ruling 2026-10-23: no history rewrite). rels are repo-relative
// paths, normally from TrackedRecordFiles. It returns the paths whose
// content changed; with dryRun it writes nothing.
//
// A file the redactor leaves unchanged keeps its bytes, and so does every
// unaffected line of a JSONL file. A file that cannot be parsed is not
// written and the call returns the error: a record that cannot be parsed
// cannot be redacted. Like every record writer it fails closed when no
// redactor can be built.
func ScrubFiles(repoRoot string, rels []string, dryRun bool) ([]string, error) {
	r, err := NewPathRedactor(repoRoot)
	if err != nil {
		return nil, fmt.Errorf("scrubbing %s: %w", repoRoot, err)
	}
	sorted := append([]string(nil), rels...)
	sort.Strings(sorted)
	var changed []string
	for _, rel := range sorted {
		mode := scrubModeFor(rel)
		if mode == scrubSkip {
			continue
		}
		did, err := scrubFile(r, repoRoot, rel, mode, dryRun)
		if err != nil {
			return changed, fmt.Errorf("scrubbing %s: %w", rel, err)
		}
		if did {
			changed = append(changed, rel)
		}
	}
	return changed, nil
}

// scrubFile redacts one file in place and reports whether it changed.
func scrubFile(r PathRedactor, repoRoot, rel string, mode scrubMode, dryRun bool) (bool, error) {
	dest := filepath.Join(repoRoot, filepath.FromSlash(rel))
	data, err := os.ReadFile(dest)
	if err != nil {
		return false, err
	}
	f := r.Content
	if mode == scrubHome {
		f = redact.HomePaths
	}
	var out []byte
	var changed bool
	switch path.Ext(rel) {
	case ".jsonl":
		out, changed, err = redactJSONLines(f, data)
	case ".yaml":
		out, changed, err = redactYAMLDoc(f, data)
	default:
		s := f(string(data))
		out, changed = []byte(s), s != string(data)
	}
	if err != nil {
		return false, err
	}
	if !changed || dryRun {
		return changed, nil
	}
	if err := writeAtomicFile(filepath.Dir(dest), ".scrub-*.tmp", dest, out); err != nil {
		return false, err
	}
	return true, nil
}
