func TestEmitAuditSentinel_RedactsReason(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	reason, raw := leakyReason(home)
	repo := t.TempDir()
	sessionID := "sess-r"
	sealedDir := filepath.Join(repo, ".punt-labs", "ethos", "sessions", "2026-07-21-"+sessionID)
	livePath := audit.LiveAuditPath(repo, sessionID)
