		Verdict: VerdictPass, Confidence: 0.8,
		FilesChanged: []FileChange{{Path: "src/[redacted-email]", Added: 1}},
		Evidence:     []EvidenceCheck{{Name: "make check", Status: EvidenceStatusPass}},
