package layout_test

import (
	"path"
	"strings"
	"testing"

	"github.com/punt-labs/ethos/v4/internal/layout"
)

func TestMatch(t *testing.T) {
	tests := []struct {
		pattern, path string
		want          bool
	}{
		{"a/b", "a/b", true},
		{"a/b", "a/c", false},
		{"a/*", "a/b", true},
		{"a/*", "a/b/c", false},
		{"a/**", "a", true},
		{"a/**", "a/b/c", true},
		{"a/**/z", "a/z", true},
		{"a/**/z", "a/b/c/z", true},
		{"a/**/z", "a/b/c", false},
		{"**/hook", "hook", true},
		{"**/hook", "x/y/hook", true},
		{"a/*.lock", "a/.lock", true},
		{"a/*.local.*", "a/q.local.yaml", true},
		{"a/*.local.*", "a/q.yaml", false},
	}
	for _, tt := range tests {
		if got := layout.Match(tt.pattern, tt.path); got != tt.want {
			t.Errorf("Match(%q, %q) = %v, want %v", tt.pattern, tt.path, got, tt.want)
		}
	}
}

func TestClassify(t *testing.T) {
	tests := []struct {
		path string
		want layout.Class
		ok   bool
	}{
		{".punt-labs/ethos/identities/bwk.yaml", layout.Source, true},
		{".punt-labs/ethos/identities/bwk.ext/quarry.yaml", layout.Source, true},
		{".punt-labs/ethos.yaml", layout.Source, true},
		{".claude/agents/bwk.md", layout.Source, true},
		{".githooks/pre-commit", layout.Source, true},
		{".punt-labs/ethos/missions/m-1/contract.yaml", layout.Blame, true},
		{".punt-labs/ethos/missions/m-1/delegations/d-1/record.yaml", layout.Blame, true},
		{".punt-labs/ethos/missions/m-1/corrections.yaml", layout.Blame, true},
		{".punt-labs/ethos/missions.jsonl", layout.Blame, true},
		{".punt-labs/ethos/adrs/DES-079.yaml", layout.Blame, true},
		{".punt-labs/ethos/missions/m-1.contract.yaml", layout.Blame, true},
		{".punt-labs/ethos/missions/m-1/delegations/d-1/prompt.md", layout.Trace, true},
		{".punt-labs/ethos/missions/m-1/reflections.yaml", layout.Trace, true},
		{".punt-labs/ethos/missions/m-1/artifacts/notes.md", layout.Trace, true},
		{".punt-labs/local/ethos/trace/missions/m-1/reflections.yaml", layout.Trace, true},
		// Class 4 wins over the class that would otherwise match.
		{".punt-labs/ethos/missions/m-1/.lock", layout.Never, true},
		{".punt-labs/ethos/missions/.create.lock", layout.Never, true},
		{".punt-labs/ethos/missions/m-1/delegations/d-1/record.yaml.tmp", layout.Never, true},
		{".punt-labs/ethos/identities/bwk.ext/quarry.local.yaml", layout.Never, true},
		{".punt-labs/ethos/identities/bwk.yaml.lock", layout.Never, true},
		{".punt-labs/local/ethos/missions/m-1/s-1.lock", layout.Never, true},
		// No entry.
		{".punt-labs/ethos/ethos.yaml", 0, false},
		{".punt-labs/ethos/unknown/file", 0, false},
		{"README.md", 0, false},
	}
	for _, tt := range tests {
		got, e, ok := layout.Classify(tt.path)
		if ok != tt.ok || got != tt.want {
			t.Errorf("Classify(%q) = %v, %q, %v; want %v, ok=%v", tt.path, got, e.Pattern, ok, tt.want, tt.ok)
		}
	}
}

func TestClassifyNormalizesPath(t *testing.T) {
	for _, p := range []string{
		"./.punt-labs/ethos/missions.jsonl",
		".punt-labs//ethos/missions.jsonl",
		".punt-labs/ethos/./missions.jsonl",
	} {
		if c, _, ok := layout.Classify(p); !ok || c != layout.Blame {
			t.Errorf("Classify(%q) = %v, %v; want blame", p, c, ok)
		}
	}
}

func TestTablePatternsWellFormed(t *testing.T) {
	for _, e := range layout.Table {
		for _, seg := range strings.Split(e.Pattern, "/") {
			if _, err := path.Match(seg, ""); err != nil {
				t.Errorf("pattern %q: bad segment %q: %v", e.Pattern, seg, err)
			}
		}
		if e.Class < layout.Source || e.Class > layout.Never {
			t.Errorf("pattern %q: invalid class %d", e.Pattern, e.Class)
		}
	}
}

// TestClassFourComesFirst pins the one overlap the table resolves by order.
func TestClassFourComesFirst(t *testing.T) {
	seenOther := false
	for _, e := range layout.Table {
		if e.Class != layout.Never {
			seenOther = true
		} else if seenOther {
			t.Errorf("class-4 entry %q follows a non-class-4 entry", e.Pattern)
		}
	}
}

// witness returns a concrete path matching pattern, so every entry can be
// checked for overlap without a hand-written list of paths.
func witness(pattern string) string {
	segs := strings.Split(pattern, "/")
	for i, s := range segs {
		if s == "**" {
			segs[i] = "x/y"
			continue
		}
		segs[i] = strings.ReplaceAll(s, "*", "x")
	}
	return strings.Join(segs, "/")
}

// conflicts returns, for each path, a description of two entries of different
// classes that both match it when neither is class 4.
func conflicts(table []layout.Entry, paths []string) []string {
	var out []string
	for _, p := range paths {
		var first *layout.Entry
		ms := layout.Matches(table, p)
		for i := range ms {
			e := ms[i]
			if e.Class == layout.Never {
				continue
			}
			if first == nil {
				first = &e
				continue
			}
			if e.Class != first.Class {
				out = append(out, p+": "+first.Pattern+" ("+first.Class.String()+") and "+e.Pattern+" ("+e.Class.String()+")")
			}
		}
	}
	return out
}

// unclassified returns the paths no entry of table matches.
func unclassified(table []layout.Entry, paths []string) []string {
	var out []string
	for _, p := range paths {
		if _, _, ok := layout.ClassifyIn(table, p); !ok {
			out = append(out, p)
		}
	}
	return out
}

func witnesses(table []layout.Entry) []string {
	out := make([]string, 0, len(table))
	for _, e := range table {
		out = append(out, witness(e.Pattern))
	}
	return out
}

func TestEntriesAreExclusive(t *testing.T) {
	paths := append(witnesses(layout.Table), writerPaths(t)...)
	for _, c := range conflicts(layout.Table, paths) {
		t.Errorf("overlapping classes: %s", c)
	}
}

// TestExclusivityDetectsOverlap is the mutant: a class-3 entry that overlaps
// the class-2 contract.yaml entry must be reported, and a class-4 overlap
// must not.
func TestExclusivityDetectsOverlap(t *testing.T) {
	mutant := append(append([]layout.Entry{}, layout.Table...),
		layout.Entry{Pattern: ".punt-labs/ethos/missions/*/*.yaml", Class: layout.Trace})
	got := conflicts(mutant, witnesses(mutant))
	if len(got) == 0 {
		t.Fatal("class-2/class-3 overlap not detected")
	}

	ok := append(append([]layout.Entry{}, layout.Table...),
		layout.Entry{Pattern: ".punt-labs/ethos/missions/*/contract.yaml", Class: layout.Never})
	if got := conflicts(ok, witnesses(ok)); len(got) != 0 {
		t.Errorf("class-4 overlap reported: %v", got)
	}
}

func TestEveryWriterPathIsClassified(t *testing.T) {
	paths := writerPaths(t)
	for _, p := range unclassified(layout.Table, paths) {
		t.Errorf("writer created %s, which no entry of layout.Table matches", p)
	}
}

// TestCoverageDetectsUnmatchedWriter is the mutant: a writer path with no
// entry, and a table that lost an entry a writer needs, must both be reported.
func TestCoverageDetectsUnmatchedWriter(t *testing.T) {
	paths := append(writerPaths(t), ".punt-labs/ethos/newthing/file.bin")
	got := unclassified(layout.Table, paths)
	if len(got) != 1 || got[0] != ".punt-labs/ethos/newthing/file.bin" {
		t.Errorf("unclassified = %v, want the new writer path only", got)
	}

	var trimmed []layout.Entry
	for _, e := range layout.Table {
		if e.Pattern != ".punt-labs/ethos/missions/*/contract.yaml" {
			trimmed = append(trimmed, e)
		}
	}
	if got := unclassified(trimmed, writerPaths(t)); len(got) == 0 {
		t.Error("removing the contract.yaml entry left every writer path classified")
	}
}

package layout_test

import (
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/punt-labs/ethos/v4/internal/attribute"
	"github.com/punt-labs/ethos/v4/internal/audit"
	"github.com/punt-labs/ethos/v4/internal/enable"
	"github.com/punt-labs/ethos/v4/internal/hook"
	"github.com/punt-labs/ethos/v4/internal/identity"
	"github.com/punt-labs/ethos/v4/internal/mission"
	"github.com/punt-labs/ethos/v4/internal/role"
	"github.com/punt-labs/ethos/v4/internal/seed"
	"github.com/punt-labs/ethos/v4/internal/team"
	"github.com/punt-labs/ethos/v4/internal/vendor"
)

// writerPaths runs the real writers against a temporary repository and returns
// every file they left in its working tree, relative to the repository root.
// Paths come from the writers and their path constructors, not from a list kept
// here, so a writer added later either appears in the result or is not
// exercised; the former fails TestEveryWriterPathIsClassified when no entry
// matches.
func writerPaths(t *testing.T) []string {
	t.Helper()

	root := t.TempDir()
	t.Setenv("HOME", t.TempDir()) // claudemd and counters lock under $HOME
	global := t.TempDir()
	ethosDir := filepath.Join(root, ".punt-labs", "ethos")

	gitIn(t, root, "init", "-q")
	// An in-tree hooks directory, so `ethos enable` writes hook files into the
	// working tree.
	gitIn(t, root, "config", "core.hooksPath", ".githooks")

	if _, err := enable.Enable(root); err != nil {
		t.Fatalf("enable: %v", err)
	}

	writeIdentityGraph(t, ethosDir)
	writeMissionRecord(t, root, global)
	writeAuditFiles(t, root)
	writeAgents(t, root, ethosDir, global)

	// The legacy-config fallback and the vendor manifest are written by
	// callers outside these packages; their constructors are the source here.
	require.NoError(t, os.WriteFile(vendor.ManifestPath(ethosDir), []byte("{}\n"), 0o644))

	var paths []string
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(root, p)
		if err != nil {
			return err
		}
		switch {
		case rel == ".git" && d.IsDir():
			return filepath.SkipDir // git's own state; hooks there are out of scope
		case d.IsDir():
			return nil
		case rel == "go.mod":
			return nil // fixture for the agent generator, not an ethos write
		}
		paths = append(paths, filepath.ToSlash(rel))
		return nil
	})
	require.NoError(t, err)
	sort.Strings(paths)
	return paths
}

func gitIn(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", append([]string{"-C", dir}, args...)...)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git %v: %v\n%s", args, err, out)
	}
}

func writeIdentityGraph(t *testing.T, ethosDir string) {
	t.Helper()

	ids := identity.NewStore(ethosDir)
	require.NoError(t, ids.Save(&identity.Identity{Name: "Brian K", Handle: "bwk", Kind: "agent",
		Personality: "kernighan", WritingStyle: "kernighan-prose", Talents: []string{"engineering"}}))
	require.NoError(t, ids.ExtSet("bwk", "quarry", "collection", "memory-bwk"))
	require.NoError(t, ids.ExtSet("bwk", "quarry", "token", "secret", identity.Local(true)))

	for _, a := range []struct {
		kind attribute.Kind
		slug string
	}{
		{attribute.Personalities, "kernighan"},
		{attribute.WritingStyles, "kernighan-prose"},
		{attribute.Talents, "engineering"},
	} {
		require.NoError(t, attribute.NewStore(ethosDir, a.kind).Save(
			&attribute.Attribute{Slug: a.slug, Content: "# " + a.slug + "\n\nBody.\n"}))
	}

	require.NoError(t, role.NewStore(ethosDir).Save(&role.Role{
		Name:  "go-specialist",
		Tools: []string{"Read", "Write", "Edit", "Bash"},
	}))
	yes := func(string) bool { return true }
	require.NoError(t, team.NewStore(ethosDir).Save(&team.Team{
		Name:    "engineering",
		Members: []team.Member{{Identity: "bwk", Role: "go-specialist"}},
	}, yes, yes))
}

func writeMissionRecord(t *testing.T, root, global string) {
	t.Helper()

	s := mission.NewStoreWithRoots(root, global).WithSessionID("sess-1")
	c := &mission.Contract{
		MissionID: "m-2026-10-24-901",
		Status:    mission.StatusOpen,
		CreatedAt: "2026-10-24T00:00:00Z",
		UpdatedAt: "2026-10-24T00:00:00Z",
		Leader:    "claude",
		Worker:    "bwk",
		Evaluator: mission.Evaluator{Handle: "djb", PinnedAt: "2026-10-24T00:00:00Z"},
		Inputs:    mission.Inputs{Ticket: "ethos-g3g3"},
		WriteSet:  []string{"internal/layout/"},
		Tools:     []string{"Read", "Write"},
		SuccessCriteria: []string{
			"make check passes",
		},
		Budget:       mission.Budget{Rounds: 2, ReflectionAfterEach: true},
		CurrentRound: 1,
	}
	require.NoError(t, s.Create(c))
	require.NoError(t, s.AppendReflection(c.MissionID, &mission.Reflection{
		Mission: c.MissionID, Round: 1, Author: "claude", Converging: true,
		Signals: []string{"green"}, Recommendation: mission.RecommendationContinue, Reason: "ok",
	}))
	require.NoError(t, s.AppendResult(c.MissionID, &mission.Result{
		Mission: c.MissionID, Round: 1, Author: "bwk", Verdict: mission.VerdictPass, Confidence: 0.8,
		Evidence: []mission.EvidenceCheck{{Name: "go test", Status: mission.EvidenceStatusPass}},
	}))
	_, err := mission.WriteDelegationSkeleton(root, c.MissionID, "d-2026-10-24-901", mission.DelegationSkeleton{
		Tier: mission.TierB, AgentType: "bwk", Prompt: []byte("do the work"),
	})
	require.NoError(t, err)
	_, err = s.Close(c.MissionID, mission.StatusClosed)
	require.NoError(t, err)
}

// writeAuditFiles creates the live audit files, seals them with the real
// sealer, and adds the names the path constructors define for the artifacts a
// seal does not produce on a healthy run.
func writeAuditFiles(t *testing.T, root string) {
	t.Helper()

	const sid = "sess-1"
	live := audit.LiveAuditPath(root, sid)
	require.NoError(t, os.MkdirAll(filepath.Dir(live), 0o755))
	require.NoError(t, os.WriteFile(live, []byte(`{"ts":"2026-10-24T00:00:00.000000001Z","tool":"Read"}`+"\n"), 0o644))
	_, err := hook.SealRepo(root, time.Date(2026, 10, 24, 1, 0, 0, 0, time.UTC), hook.SealOptions{})
	require.NoError(t, err)

	const mid = "m-2026-10-24-902"
	sessionDir := filepath.Join(audit.SealedSessionsBase(root), "2026-10-24-"+sid)
	missionDir := audit.SealedMissionDir(root, mid)
	sess := audit.ChunkName{Namespace: audit.SessionNS, First: 1, Last: 2}
	msn := audit.ChunkName{Namespace: audit.MissionNS, Session: sid, First: 1, Last: 2}

	for _, p := range []string{
		audit.LiveAuditLockPath(root, sid),
		audit.LiveMissionLockPath(root, mid, sid),
		audit.LiveMissionLogPath(root, mid, sid),
		audit.MissionResiduePath(root, mid),
		audit.MissionLegacyLogPath(root, mid),
		filepath.Join(sessionDir, "audit.jsonl"),
		filepath.Join(sessionDir, sess.ChunkFile()),
		filepath.Join(sessionDir, sess.TempFile()),
		filepath.Join(sessionDir, sess.MarkerFile()),
		filepath.Join(sessionDir, sess.Stem()+".jsonl.corrupt"),
		filepath.Join(sessionDir, sess.Stem()+".jsonl.corrupt-abc123"),
		filepath.Join(missionDir, msn.ChunkFile()),
		filepath.Join(missionDir, msn.TempFile()),
		filepath.Join(missionDir, msn.MarkerFile()),
		filepath.Join(missionDir, msn.Stem()+".jsonl.corrupt"),
		filepath.Join(missionDir, msn.Stem()+".jsonl.corrupt-abc123"),
	} {
		require.NoError(t, os.MkdirAll(filepath.Dir(p), 0o755))
		require.NoError(t, os.WriteFile(p, nil, 0o644))
	}
}

// writeAgents runs the three writers of .claude/agents/<name>.md: the
// SessionStart generator, the installer, and the seeder.
func writeAgents(t *testing.T, root, ethosDir, global string) {
	t.Helper()

	require.NoError(t, os.WriteFile(filepath.Join(root, "go.mod"), []byte("module example.com/t\n"), 0o644))
	require.NoError(t, os.WriteFile(filepath.Join(root, ".punt-labs", "ethos.yaml"),
		[]byte("agent: claude\nteam: engineering\n"), 0o644))
	// A second member, so the generator has an agent other than the main one.
	require.NoError(t, team.NewStore(ethosDir).Save(&team.Team{
		Name: "engineering",
		Members: []team.Member{
			{Identity: "claude", Role: "go-specialist"},
			{Identity: "bwk", Role: "go-specialist"},
		},
	}, func(string) bool { return true }, func(string) bool { return true }))
	require.NoError(t, identity.NewStore(ethosDir).Save(&identity.Identity{
		Name: "Claude", Handle: "claude", Kind: "human"}))

	ids := identity.NewLayeredStore(identity.NewStore(ethosDir), identity.NewStore(global))
	teams := team.NewLayeredStore(ethosDir, global)
	roles := role.NewLayeredStore(ethosDir, global)
	require.NoError(t, hook.GenerateAgentFiles(root, ids, teams, roles))

	require.NoError(t, os.MkdirAll(filepath.Join(ethosDir, "agents"), 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(ethosDir, "agents", "stub.md"), []byte("# stub\n"), 0o644))
	t.Chdir(root)
	_, err := hook.InstallAgentDefinitions(ethosDir, map[string]bool{})
	require.NoError(t, err)

	_, err = seed.SeedVersionWithBundleDir(filepath.Join(global, "seed"), filepath.Join(global, "skills"),
		filepath.Join(root, ".claude", "agents"), "", "", "test", false)
	require.NoError(t, err)
}

