package main

import (
	"fmt"
	"math/rand"
	"path"
	"strings"
)

func matchSegments(pat, segs []string) bool {
	for len(pat) > 0 {
		if pat[0] == "**" {
			rest := pat[1:]
			for i := 0; i <= len(segs); i++ {
				if matchSegments(rest, segs[i:]) {
					return true
				}
			}
			return false
		}
		if len(segs) == 0 {
			return false
		}
		ok, err := path.Match(pat[0], segs[0])
		if err != nil || !ok {
			return false
		}
		pat, segs = pat[1:], segs[1:]
	}
	return len(segs) == 0
}

func Match(p, s string) bool { return matchSegments(strings.Split(p, "/"), strings.Split(s, "/")) }

func strs(n int) []string {
	out := []string{}
	var rec func(s string)
	rec = func(s string) {
		if s != "" {
			out = append(out, s)
		}
		if len(s) == n {
			return
		}
		rec(s + "a")
		rec(s + "b")
	}
	rec("")
	return out
}

func main() {
	segStrs := strs(4)
	var paths []string
	for _, a := range segStrs {
		paths = append(paths, a)
		for _, b := range segStrs {
			paths = append(paths, a+"/"+b)
			for _, c := range segStrs {
				paths = append(paths, a+"/"+b+"/"+c)
			}
		}
	}
	toks := []string{"a", "b", "?", "*"}
	var segs []string
	segs = append(segs, "**")
	for _, x := range toks {
		segs = append(segs, x)
		for _, y := range toks {
			segs = append(segs, x+y)
		}
	}
	gen := func() string {
		n := 1 + rand.Intn(3)
		var p []string
		for i := 0; i < n; i++ {
			p = append(p, segs[rand.Intn(len(segs))])
		}
		return strings.Join(p, "/")
	}
	bad := 0
	for it := 0; it < 20000 && bad < 20; it++ {
		a, b := gen(), gen()
		brute := false
		for _, p := range paths {
			if Match(a, p) && Match(b, p) {
				brute = true
				break
			}
		}
		if got := Overlap(a, b); got != brute {
			bad++
			fmt.Printf("MISMATCH %q %q overlap=%v brute=%v\n", a, b, got, brute)
		}
	}
	fmt.Println("done, mismatches:", bad)
}

