// PathValue is a string held in a `redact:"path"` field, with the field path
// that names it, such as "Tools[0]".
type PathValue struct {
	Name  string
	Value string
}

// PathValues returns every string inside a `redact:"path"` field of v, in
// field order. It lets a writer check the result of the path pass, which
// RecordPaths applies but cannot judge.
func PathValues[T any](v T) []PathValue {
	var out []PathValue
	collectPaths(reflect.ValueOf(&v).Elem(), false, "", &out)
	return out
}

func collectPaths(v reflect.Value, inPath bool, name string, out *[]PathValue) {
	switch v.Kind() {
	case reflect.String:
		if inPath {
			*out = append(*out, PathValue{Name: name, Value: v.String()})
		}
	case reflect.Struct:
		t := v.Type()
		for i := 0; i < t.NumField(); i++ {
			sf := t.Field(i)
			tag := sf.Tag.Get("redact")
			if !sf.IsExported() || tag == "keep" {
				continue
			}
			sub := sf.Name
			if name != "" {
				sub = name + "." + sf.Name
			}
			collectPaths(v.Field(i), inPath || tag == "path", sub, out)
		}
	case reflect.Pointer, reflect.Interface:
		if !v.IsNil() {
			collectPaths(v.Elem(), inPath, name, out)
		}
	case reflect.Slice, reflect.Array:
		for i := 0; i < v.Len(); i++ {
			collectPaths(v.Index(i), inPath, fmt.Sprintf("%s[%d]", name, i), out)
		}
	case reflect.Map:
		keys := v.MapKeys()
		sort.Slice(keys, func(a, b int) bool { return fmt.Sprint(keys[a]) < fmt.Sprint(keys[b]) })
		for _, k := range keys {
			collectPaths(v.MapIndex(k), inPath, fmt.Sprintf("%s[%v]", name, k), out)
		}
	}
}
EOF
