// leakChecker is the one question every tracked-tree writer asks of what it
// is about to write: does it name a home directory. It carries this process's
// home, or knows that it cannot name one.
type leakChecker struct {
	home  string
	known bool
}

// newLeakChecker resolves the home directory of this process. When it cannot,
// the checker treats every absolute path as a leak: with no home to compare
// against, a path cannot be cleared.
func newLeakChecker() leakChecker {
	home, err := os.UserHomeDir()
	if err != nil || !usablePrefix(home) {
		return leakChecker{}
	}
	return leakChecker{home: filepath.Clean(home), known: true}
}

// rule names the rule s breaks, in words that do not quote s, or returns "".
func (c leakChecker) rule(s string) string {
	if r := redact.LeakRule(s, c.home); r != "" {
		return r
	}
	if !c.known && redact.AbsolutePath(s) {
		return "holds an absolute path while the home directory is unknown"
	}
	return ""
}

// LeakRule names the rule s breaks against this process's home directory, or
// returns "" when s names no home. Without a resolvable home directory every
// absolute path breaks a rule.
func LeakRule(s string) string { return newLeakChecker().rule(s) }

// guardWrite is the check at the sink of every mission-tree writer. It takes
// the final bytes bound for dest and refuses them if they name a home, whatever
// pass produced them. The raw bytes are checked, and so is the decoded form of
// a YAML or JSON file, so a tag, a key of any kind or an escaped spelling is
// covered too. The error names the file's base name and the place, never the
// value.
func guardWrite(dest string, data []byte) error {
	base := filepath.Base(dest)
	c := newLeakChecker()
	if r := c.rule(string(data)); r != "" {
		return fmt.Errorf("refusing to write %s: its content %s; remove or rephrase it", base, r)
	}
	var where, r string
	switch strings.ToLower(filepath.Ext(base)) {
	case ".yaml", ".yml":
		where, r = guardYAML(c, data)
	case ".json", ".jsonl":
		where, r = guardJSON(c, data)
	}
	if r != "" {
		return fmt.Errorf("refusing to write %s: %s %s; remove or rephrase it", base, where, r)
	}
	return nil
}

// guardYAML reports the first place in the decoded documents that breaks a
// rule. A file that does not decode is left to the raw check.
func guardYAML(c leakChecker, data []byte) (string, string) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	for {
		var doc yaml.Node
		if err := dec.Decode(&doc); err != nil {
			return "", ""
		}
		if where, r := guardNode(c, &doc); r != "" {
			return where, r
		}
	}
}

func guardNode(c leakChecker, n *yaml.Node) (string, string) {
	for _, s := range []string{n.Value, n.Tag, n.Anchor, n.HeadComment, n.LineComment, n.FootComment} {
		if r := c.rule(s); r != "" {
			return fmt.Sprintf("yaml line %d", n.Line), r
		}
	}
	for _, k := range n.Content {
		if where, r := guardNode(c, k); r != "" {
			return where, r
		}
	}
	return "", ""
}

// guardJSON reports the first line of a JSON or JSON-lines file with a string
// or object key that breaks a rule.
func guardJSON(c leakChecker, data []byte) (string, string) {
	for i, line := range bytes.Split(data, []byte("\n")) {
		if len(bytes.TrimSpace(line)) == 0 {
			continue
		}
		dec := json.NewDecoder(bytes.NewReader(line))
		for {
			var v any
			if err := dec.Decode(&v); err != nil {
				if !errors.Is(err, io.EOF) {
					break
				}
				break
			}
			if r := guardValue(c, v); r != "" {
				return fmt.Sprintf("line %d", i+1), r
			}
		}
	}
	return "", ""
}

func guardValue(c leakChecker, v any) string {
	switch x := v.(type) {
	case string:
		return c.rule(x)
	case []any:
		for _, e := range x {
			if r := guardValue(c, e); r != "" {
				return r
			}
		}
	case map[string]any:
		for k, e := range x {
			if r := c.rule(k); r != "" {
				return r
			}
			if r := guardValue(c, e); r != "" {
				return r
			}
		}
	}
	return ""
}
