		if s, ok := cleaned[k].(string); ok {
			minimal[k] = s
		}
	}
	out, _ := json.Marshal(minimal)
	return out
}

// lineLeaks reports whether the raw bytes or any decoded string or key of a
// JSON line break a rule.
func lineLeaks(line []byte) bool {
	if mission.LeakRule(string(line)) != "" {
		return true
	}
	dec := json.NewDecoder(bytes.NewReader(line))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return false
	}
	return valueLeaks(v)
}

func valueLeaks(v any) bool {
	switch x := v.(type) {
	case string:
		return mission.LeakRule(x) != ""
	case []any:
		for _, e := range x {
			if valueLeaks(e) {
				return true
			}
		}
	case map[string]any:
		for k, e := range x {
			if mission.LeakRule(k) != "" || valueLeaks(e) {
