			}
		}
	}
	return false
}

// scrubAuditValue replaces every string that leaks by redactedPath and every
// key that leaks by redactedKey, numbering collisions in sorted order.
func scrubAuditValue(v any) any {
	switch x := v.(type) {
	case string:
		if mission.LeakRule(x) != "" {
			return redactedPath
		}
		return x
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			out[i] = scrubAuditValue(e)
		}
		return out
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		out := make(map[string]any, len(x))
		for _, k := range keys {
			nk := k
			if mission.LeakRule(k) != "" {
				nk = redactedKey
			}
			out[freeKey(out, nk)] = scrubAuditValue(x[k])
		}
		return out
	}
	return v
}
