// guardAuditLineWhy is guardAuditLine returning the rule that forced a
// rewrite instead of reporting it; the rule is "" when the line was clean.
func guardAuditLineWhy(line []byte) ([]byte, string) {
	rule := lineRule(line)
	if rule == "" {
		return line, ""
	}
	dec := json.NewDecoder(bytes.NewReader(line))
	dec.UseNumber()
