// lineRule names the rule the raw bytes or any decoded string or key of a
// JSON line break, or returns "".
func lineRule(line []byte) string {
	if r := mission.LeakRule(string(line)); r != "" {
		return r
	}
	dec := json.NewDecoder(bytes.NewReader(line))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return ""
	}
	return valueRule(v)
}

func lineLeaks(line []byte) bool { return lineRule(line) != "" }

func valueRule(v any) string {
	switch x := v.(type) {
	case string:
		return mission.LeakRule(x)
	case []any:
		for _, e := range x {
			if r := valueRule(e); r != "" {
				return r
			}
		}
	case map[string]any:
		for k, e := range x {
			if r := mission.LeakRule(k); r != "" {
				return r
			}
			if r := valueRule(e); r != "" {
				return r
			}
		}
	}
	return ""
}

