		{"bad binary", "r.yaml", "context: !!binary '***'\n", true},
		{"second document", "r.yaml", "a: ok\n---\nb: ~[redacted-user]/x\n", true},
		{"second document broken", "r.yaml", "a: ok\n---\nb: [\n", true},
