type TrackedFile struct {
	Path string
	Data []byte
	Perm os.FileMode
}

// WriteTrackedFiles writes files for a caller outside this package whose
// output lands in a tracked tree (the mission export). Every payload is
// guarded before any file is touched. Each is then written to a temp file in
// its own directory and fsynced, and only when all are on disk are the
// renames made, so a failure leaves no truncated file. A failure removes the
// temp files and any destination the call created; a destination that
// already existed was replaced by a complete file or left as it was.
func WriteTrackedFiles(files ...TrackedFile) error {
	for _, f := range files {
		if err := guardWrite(f.Path, f.Data); err != nil {
			return err
		}
	}
	temps := make([]string, len(files))
	cleanup := func() {
		for _, t := range temps {
			if t != "" {
				_ = os.Remove(t)
			}
		}
	}
	for i, f := range files {
		tmp, err := os.CreateTemp(filepath.Dir(f.Path), ".export-*.tmp")
		if err != nil {
			cleanup()
			return ioErr("creating temp file for", f.Path, err)
		}
		temps[i] = tmp.Name()
		if _, err := tmp.Write(f.Data); err != nil {
			_ = tmp.Close()
			cleanup()
			return ioErr("writing", f.Path, err)
		}
		if err := tmp.Chmod(f.Perm); err != nil {
			_ = tmp.Close()
			cleanup()
			return ioErr("chmod", f.Path, err)
		}
		if err := tmp.Sync(); err != nil {
			_ = tmp.Close()
			cleanup()
			return ioErr("syncing", f.Path, err)
		}
		if err := tmp.Close(); err != nil {
			cleanup()
			return ioErr("closing", f.Path, err)
		}
	}
	var created []string
	for i, f := range files {
		_, statErr := os.Lstat(f.Path)
		if err := os.Rename(temps[i], f.Path); err != nil {
			cleanup()
			for _, c := range created {
				_ = os.Remove(c)
			}
			return ioErr("renaming the temp file to", f.Path, err)
		}
		temps[i] = ""
		if statErr != nil {
			created = append(created, f.Path)
		}
	}
	return nil
}
