// guarded before any file is touched. Each is then written to a temp file in
// its own directory and fsynced. Only when all are on disk are the swaps made:
// an existing destination is renamed aside, the temp file is renamed into its
// place, and a failure at any step puts every swapped destination back as it
// was, so a failed re-export never leaves a mismatched pair. Once all swaps
// have succeeded the backups are removed and the directories fsynced. A
// failure to clean up or restore is joined into the returned error.
//
// A file's mode is exactly Perm: it is set with chmod, so the umask does not
// narrow it.
func WriteTrackedFiles(files ...TrackedFile) error {
	for _, f := range files {
		if err := guardWrite(f.Path, f.Data); err != nil {
			return err
		}
	}
	temps := make([]string, len(files))
	removeTemps := func() error {
		var errs []error
		for _, t := range temps {
			if t == "" {
				continue
			}
			if err := os.Remove(t); err != nil && !errors.Is(err, fs.ErrNotExist) {
				errs = append(errs, ioErr("removing temp file", t, err))
			}
		}
		return errors.Join(errs...)
	}
