		tmp, err := writeTrackedTemp(f)
		if tmp != "" {
			temps[i] = tmp
		}
		if err != nil {
			return errors.Join(err, removeTemps())
		}
	}

	type swap struct {
		dest, backup string // backup is "" when dest did not exist
		done         bool   // the new file is in place
	}
	swaps := make([]swap, len(files))
	rollback := func() error {
		var errs []error
		for i := len(swaps) - 1; i >= 0; i-- {
			sw := swaps[i]
			if sw.done {
				if err := os.Remove(sw.dest); err != nil && !errors.Is(err, fs.ErrNotExist) {
					errs = append(errs, ioErr("removing", sw.dest, err))
				}
			}
			if sw.backup != "" {
				if err := os.Rename(sw.backup, sw.dest); err != nil {
					errs = append(errs, ioErr("restoring", sw.dest, err))
				}
			}
		}
		return errors.Join(errs...)
	}
	fail := func(err error) error {
		return errors.Join(err, rollback(), removeTemps())
	}
	for i, f := range files {
		swaps[i].dest = f.Path
		if _, err := os.Lstat(f.Path); err == nil {
			backup := fmt.Sprintf("%s.export-bak-%d", f.Path, time.Now().UnixNano())
			if err := os.Rename(f.Path, backup); err != nil {
				return fail(ioErr("moving aside", f.Path, err))
			}
			swaps[i].backup = backup
		} else if !errors.Is(err, fs.ErrNotExist) {
			return fail(ioErr("checking", f.Path, err))
		}
		if err := os.Rename(temps[i], f.Path); err != nil {
			return fail(ioErr("renaming the temp file to", f.Path, err))
		}
		temps[i] = ""
		swaps[i].done = true
	}

	var errs []error
	for _, sw := range swaps {
		if sw.backup == "" {
			continue
		}
		if err := os.Remove(sw.backup); err != nil && !errors.Is(err, fs.ErrNotExist) {
			errs = append(errs, ioErr("removing backup of", sw.dest, err))
		}
	}
	seen := map[string]bool{}
	for _, f := range files {
		dir := filepath.Dir(f.Path)
		if seen[dir] {
			continue
		}
		seen[dir] = true
		if err := syncDir(dir); err != nil {
			errs = append(errs, ioErr("syncing directory of", f.Path, err))
		}
	}
