}

// writeTrackedTemp writes f's data to a temp file beside f.Path, sets its
// mode, fsyncs and closes it, and returns the temp file's name (also on a
// failure after it was created, so the caller can remove it).
func writeTrackedTemp(f TrackedFile) (string, error) {
	tmp, err := os.CreateTemp(filepath.Dir(f.Path), ".export-*.tmp")
	if err != nil {
		return "", ioErr("creating temp file for", f.Path, err)
	}
	name := tmp.Name()
	if _, err := tmp.Write(f.Data); err != nil {
		_ = tmp.Close()
		return name, ioErr("writing", f.Path, err)
	}
	if err := tmp.Chmod(f.Perm); err != nil {
		_ = tmp.Close()
		return name, ioErr("chmod", f.Path, err)
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return name, ioErr("syncing", f.Path, err)
	}
	if err := tmp.Close(); err != nil {
		return name, ioErr("closing", f.Path, err)
	}
	return name, nil
}

// syncDir fsyncs a directory so the renames in it are durable.
func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	if err := d.Sync(); err != nil {
		_ = d.Close()
		return err
	}
	return d.Close()
}
