// the result (len+1 entries) to the offset in s it came from.
func unescapeSlashes(s string) (string, []int) {
	var b strings.Builder
	back := make([]int, 0, len(s)+1)
	for i := 0; i < len(s); i++ {
		back = append(back, i)
		if s[i] == '\\\\' && i+1 < len(s) && s[i+1] == '/' {
			i++
