// parseRunAll returns the RunAll declaration in file.
func parseRunAll(t *testing.T, file string) *ast.FuncDecl {
	t.Helper()
	f, err := parser.ParseFile(token.NewFileSet(), file, nil, 0)
	require.NoError(t, err)
