	"gopkg.in/yaml.v3"
)

func genericYAML(b []byte) any {
	var v any
	_ = yaml.Unmarshal(b, &v)
	return v
}

func keysLost(in, out any, prefix string, acc *[]string) {
	switch x := in.(type) {
	case map[string]any:
		o, _ := out.(map[string]any)
		for k, v := range x {
			ov, ok := o[k]
			if !ok {
				*acc = append(*acc, prefix+"."+k)
				continue
			}
			keysLost(v, ov, prefix+"."+k, acc)
		}
	case []any:
		o, _ := out.([]any)
		for i, v := range x {
			if i >= len(o) {
				*acc = append(*acc, fmt.Sprintf("%s[%d]", prefix, i))
				continue
			}
			keysLost(v, o[i], fmt.Sprintf("%s[%d]", prefix, i), acc)
		}
	default:
		if fmt.Sprint(in) != fmt.Sprint(out) && !(in == nil && out == nil) {
			*acc = append(*acc, fmt.Sprintf("%s: %v -> %v", prefix, in, out))
		}
	}
}

func TestProbeRealTree(t *testing.T) {
	root := "../../.punt-labs/ethos"
