	_ = filepath.Walk(root, func(p string, fi os.FileInfo, err error) error {
		if err != nil || fi.IsDir() {
			return nil
		}
		if strings.Contains(p, "/sessions/") {
			return nil
		}
		ext := filepath.Ext(p)
		if ext != ".yaml" && ext != ".jsonl" {
			return nil
