// dropped reports keys in a not present in b (recursively, maps only).
func dropped(a, b any, prefix string, out *[]string) {
	am, ok := a.(map[string]any)
	if !ok {
		if as, ok := a.([]any); ok {
			bs, _ := b.([]any)
			for i := range as {
				var be any
				if i < len(bs) {
					be = bs[i]
				}
				dropped(as[i], be, fmt.Sprintf("%s[%d]", prefix, i), out)
			}
		}
		return
	}
	bm, _ := b.(map[string]any)
	for k, v := range am {
		bv, ok := bm[k]
		if !ok {
			*out = append(*out, prefix+"."+k)
			continue
		}
		dropped(v, bv, prefix+"."+k, out)
	}
}

func TestZZProbeTree(t *testing.T) {
	root := "../../.punt-labs/ethos"
	n, refused, lossy := 0, 0, 0
	_ = filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		rel, _ := filepath.Rel("../..", p)
		rel = filepath.ToSlash(rel)
		if !scrubbable(rel) || strings.HasSuffix(rel, ".md") {
			return nil
		}
		data, _ := os.ReadFile(p)
		n++
		out, gerr := guardWrite(p, data)
		if gerr != nil {
			refused++
			fmt.Fprintf(os.Stderr, "REFUSED %s: %v\n", rel, gerr)
			return nil
		}
		var miss []string
		if strings.HasSuffix(rel, ".jsonl") {
			al := bytes.Split(data, []byte("\n"))
			bl := bytes.Split(out, []byte("\n"))
			for i := range al {
				if len(bytes.TrimSpace(al[i])) == 0 || i >= len(bl) {
					continue
				}
				var a, b any
				_ = json.Unmarshal(al[i], &a)
				_ = json.Unmarshal(bl[i], &b)
				dropped(a, b, fmt.Sprintf("line%d", i+1), &miss)
			}
		} else {
			a, b := genericYAML(data), genericYAML(out)
			dropped(a, b, "", &miss)
			// also value changes
			if len(miss) == 0 && !reflect.DeepEqual(a, b) {
				fmt.Fprintf(os.Stderr, "VALUECHANGE %s\n", rel)
			}
		}
		if len(miss) > 0 {
			lossy++
			fmt.Fprintf(os.Stderr, "DROPPED %s: %v\n", rel, miss)
		}
		return nil
	})
	fmt.Fprintf(os.Stderr, "files=%d refused=%d lossy=%d\n", n, refused, lossy)
}

