			for _, c := range n.Content {
				if k, ok := unknownYAMLKey(c, t.Elem()); ok {
					return k, true
				}
			}
		}
	}
	return "", false
}

// unknownJSONKey is unknownYAMLKey for a decoded JSON value, matching field
