// in is in out with the same value (a legacy spelling under its canonical
// name), and a key only one side has holds a zero value there. Scalars are
// compared by their text, so style and quoting do not matter.
func sameYAML(in, out *yaml.Node) bool {
	for in.Kind == yaml.DocumentNode && len(in.Content) == 1 {
		in = in.Content[0]
	}
	for out.Kind == yaml.DocumentNode && len(out.Content) == 1 {
		out = out.Content[0]
	}
	if zeroYAML(in) && zeroYAML(out) {
		return true
	}
	if in.Kind != out.Kind {
		return false
	}
	switch in.Kind {
	case yaml.ScalarNode:
		return in.Value == out.Value
	case yaml.SequenceNode:
		if len(in.Content) != len(out.Content) {
			return false
		}
		for i := range in.Content {
			if !sameYAML(in.Content[i], out.Content[i]) {
				return false
			}
		}
		return true
	case yaml.MappingNode:
