		if canon == k {
			if _, ok := im[old]; ok {
				return true
			}
		}
	}
	return false
}

func yamlMap(n *yaml.Node) map[string]*yaml.Node {
	m := make(map[string]*yaml.Node, len(n.Content)/2)
	for i := 0; i+1 < len(n.Content); i += 2 {
		m[n.Content[i].Value] = n.Content[i+1]
	}
	return m
}

// zeroYAML reports whether n holds a zero value: null, an empty or zero
// scalar, or an empty or all-zero collection.
func zeroYAML(n *yaml.Node) bool {
	switch n.Kind {
	case yaml.ScalarNode:
		if n.Tag == "!!null" {
			return true
		}
		switch n.Value {
		case "", "0", "false", "~", "null":
			return true
		}
		return false
	case yaml.MappingNode:
		for i := 1; i < len(n.Content); i += 2 {
			if !zeroYAML(n.Content[i]) {
				return false
			}
		}
		return true
	case yaml.SequenceNode:
		return len(n.Content) == 0
	}
	return false
}

// sameJSON is sameYAML for decoded JSON values (numbers as json.Number).
func sameJSON(in, out any) bool {
	if zeroJSON(in) && zeroJSON(out) {
		return true
	}
	switch x := in.(type) {
	case map[string]any:
		y, ok := out.(map[string]any)
		if !ok {
			return false
		}
		for k, iv := range x {
			ov, ok := y[k]
			if !ok {
				if alt, has := legacyKeys[k]; has {
					if _, both := x[alt]; !both {
						ov, ok = y[alt]
					}
				}
			}
			if !ok {
				if !zeroJSON(iv) {
					return false
				}
				continue
			}
			if !sameJSON(iv, ov) {
				return false
			}
		}
		for k, ov := range y {
			if _, ok := x[k]; ok {
				continue
			}
			legacy := false
			for old, canon := range legacyKeys {
				if _, has := x[old]; has && canon == k {
					legacy = true
				}
			}
			if !legacy && !zeroJSON(ov) {
				return false
			}
		}
		return true
	case []any:
		y, ok := out.([]any)
		if !ok || len(x) != len(y) {
			return false
		}
		for i := range x {
			if !sameJSON(x[i], y[i]) {
				return false
			}
		}
		return true
	}
	return reflect.DeepEqual(in, out)
}

func zeroJSON(v any) bool {
	switch x := v.(type) {
	case nil:
		return true
	case string:
		return x == ""
	case bool:
		return !x
	case json.Number:
		return x == "0"
	case []any:
		return len(x) == 0
	case map[string]any:
		for _, e := range x {
			if !zeroJSON(e) {
				return false
			}
		}
		return true
	}
	return false
}

