package resolve

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// Without git, the hand rules stop at GIT_CEILING_DIRECTORIES exactly where
// git does: a ceiling that is a proper ancestor of the (physical) working
// directory is never examined, nor is anything above it; an entry equal to
// the working directory, a relative entry and an unresolvable entry are
// ignored; entries are resolved to real paths unless an empty entry came
// before them. Each case is checked against git itself.
func TestHandRulesHonourCeilingLikeGit(t *testing.T) {
	requireGit(t)
	cases := map[string]struct {
		ceiling func(base, outer, start, link string) string
		start   func(outer, link string) string
	}{
		"ceiling below the repository":     {ceiling: func(_, outer, _, _ string) string { return filepath.Join(outer, "a") }},
		"ceiling at the repository":        {ceiling: func(_, outer, _, _ string) string { return outer }},
		"ceiling above the repository":     {ceiling: func(base, _, _, _ string) string { return base }},
		"ceiling equal to the start":       {ceiling: func(_, _, start, _ string) string { return start }},
		"trailing slash":                   {ceiling: func(_, outer, _, _ string) string { return outer + "/" }},
		"dot-dot in the entry":             {ceiling: func(_, outer, _, _ string) string { return filepath.Join(outer, "a") + "/.." }},
		"symlink entry is resolved":        {ceiling: func(_, _, _, link string) string { return link }},
		"after an empty entry, kept as is": {ceiling: func(_, _, _, link string) string { return ":" + link }},
		"relative entry ignored":           {ceiling: func(_, _, _, _ string) string { return "outer" }},
		"nonexistent entry ignored":        {ceiling: func(base, _, _, _ string) string { return filepath.Join(base, "nope") }},
		"root ceiling":                     {ceiling: func(_, _, _, _ string) string { return "/" }},
		"several entries, longest wins": {ceiling: func(base, outer, _, _ string) string {
			return base + string(os.PathListSeparator) + filepath.Join(outer, "a")
		}},
		"start through a symlink": {
			ceiling: func(_, outer, _, _ string) string { return outer },
			start:   func(_, link string) string { return filepath.Join(link, "a", "b") },
		},
	}
	for name, c := range cases {
		t.Run(name, func(t *testing.T) {
			base := t.TempDir()
			outer := filepath.Join(base, "outer")
			makeGitDirAt(t, filepath.Join(outer, ".git"))
			start := filepath.Join(outer, "a", "b")
			require.NoError(t, os.MkdirAll(start, 0o755))
			link := filepath.Join(base, "link")
			if err := os.Symlink(outer, link); err != nil {
				t.Skipf("symlinks unavailable: %v", err)
			}
			if c.start != nil {
				start = c.start(outer, link)
			}
			t.Setenv("GIT_CEILING_DIRECTORIES", c.ceiling(base, outer, start, link))
			t.Chdir(start)

			want, gitErr := gitTopLevel(t, start)
			hideGit(t)
			var got string
			var err error
			captureStderr(t, func() { got, err = LocateRepoRoot() })
			if gitErr != nil {
				assert.ErrorIs(t, err, ErrNotInRepo, "git stops at the ceiling, so must the hand rules (got %q)", got)
				return
			}
			require.NoError(t, err)
			assert.Equal(t, realpath(t, want), realpath(t, got))
		})
	}
}

import sys

root = sys.argv[1]


def sub(s, old, new):
    assert s.count(old) == 1, old
    return s.replace(old, new)


p = root + "/internal/resolve/resolve.go"
s = open(p).read()
start = s.index("// ceilings returns the GIT_CEILING_DIRECTORIES entries")
end = s.index("// ancestorAt returns the ancestor of start")
s = s[:start] + '''// realDir returns p with symlinks resolved, or p cleaned when it cannot be.
func realDir(p string) string {
	if r, err := filepath.EvalSymlinks(p); err == nil {
		return r
	}
	return filepath.Clean(p)
}

// firstDotGit returns the nearest .git entry git examines from start, or "".
func firstDotGit(start string) string {
	for _, dir := range gitWalk(start) {
		dot := filepath.Join(dir, ".git")
		if _, err := os.Lstat(dot); !errors.Is(err, fs.ErrNotExist) {
			return dot
		}
	}
	return ""
}

// gitWalk returns the directories git examines for a repository from start,
// nearest first, as git's setup_git_directory does: from the physical working
// directory (getcwd resolves symlinks) upward, stopping before the longest
// GIT_CEILING_DIRECTORIES entry that is a proper ancestor of it, so neither
// that entry nor anything above it is examined.
func gitWalk(start string) []string {
	dir := realDir(start)
	off := ceilingOffset(dir, gitCeilings())
	dirs := []string{dir}
	for {
		parent := filepath.Dir(dir)
		if parent == dir {
			return dirs
		}
		// git cuts the path at the separator that ends parent: index 0 for
		// the root, else the length of parent.
		cut := len(parent)
		if parent == string(filepath.Separator) {
			cut = 0
		}
		if cut <= off {
			return dirs
		}
		dirs = append(dirs, parent)
		dir = parent
	}
}

// gitCeilings returns the GIT_CEILING_DIRECTORIES entries as git uses them
// (canonicalize_ceiling_entry): a relative entry is ignored; an entry before
// any empty entry is resolved to its real path, and ignored when that fails;
// an entry after an empty entry is kept exactly as written.
func gitCeilings() []string {
	var out []string
	asWritten := false
	for _, c := range strings.Split(os.Getenv("GIT_CEILING_DIRECTORIES"), string(os.PathListSeparator)) {
		switch {
		case c == "":
			asWritten = true
		case !filepath.IsAbs(c):
		case asWritten:
			out = append(out, c)
		default:
			if r, err := filepath.EvalSymlinks(c); err == nil {
				out = append(out, r)
			}
		}
	}
	return out
}

// ceilingOffset is git's longest_ancestor_length: the length of the longest
// ceiling that is a proper ancestor of path (a trailing separator not
// counted), or -1 when none is. The comparison is on the strings, as git's.
func ceilingOffset(path string, ceils []string) int {
	sep := string(filepath.Separator)
	if path == sep {
		return -1
	}
	longest := -1
	for _, c := range ceils {
		n := len(strings.TrimSuffix(c, sep))
		if n == len(c) || c == sep {
			n = len(c)
			if strings.HasSuffix(c, sep) {
				n--
			}
		}
		if !strings.HasPrefix(path, c[:n]) || len(path) <= n+1 || path[n:n+1] != sep {
			continue
		}
		longest = max(longest, n)
	}
	return longest
}

