func TestZZProbeRealData(t *testing.T) {
	root := os.Getenv("PROBE_DATA")
	if root == "" {
		t.Skip()
	}
	var lines []string
	_ = filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		ext := strings.ToLower(filepath.Ext(p))
		if ext != ".yaml" && ext != ".yml" && ext != ".json" && ext != ".jsonl" {
			return nil
		}
		data, err := os.ReadFile(p)
		if err != nil {
			return nil
		}
		rel, _ := filepath.Rel(root, p)
		out, gErr := guardWrite(p, data)
		if gErr != nil {
			lines = append(lines, fmt.Sprintf("ERR %s: %v", rel, gErr))
			return nil
		}
		lines = append(lines, fmt.Sprintf("OK  %s %x", rel, sha256.Sum256(out)))
		return nil
	})
	sort.Strings(lines)
	_ = os.WriteFile(os.Getenv("PROBE_OUT"), []byte(strings.Join(lines, "\n")+"\n"), 0o644)
}

