			if !f.IsExported() {
				continue
			}
			fmt.Printf("%s.%s %s yaml=%q json=%q\n", path, f.Name, f.Type, f.Tag.Get("yaml"), f.Tag.Get("json"))
			walkT(f.Type, path+"."+f.Name, seen)
		}
	case reflect.Slice, reflect.Array, reflect.Map:
		walkT(t.Elem(), path+"[]", seen)
	}
}

