func TestZZMainGone(t *testing.T) {
	for _, mode := range []string{"deleted", "moved"} {
		for _, withGit := range []bool{true, false} {
			t.Run(mode+map[bool]string{true: " git", false: " nogit"}[withGit], func(t *testing.T) {
				requireGit(t)
				base := t.TempDir()
				main := filepath.Join(base, "main")
				initRepo(t, main)
				wt := filepath.Join(base, "wt")
				gitRun(t, "-C", main, "worktree", "add", "-q", wt)
				if mode == "deleted" {
					if err := os.RemoveAll(main); err != nil {
						t.Fatal(err)
					}
				} else {
					if err := os.Rename(main, filepath.Join(base, "elsewhere")); err != nil {
						t.Fatal(err)
					}
				}
				t.Chdir(wt)
				if !withGit {
					hideGit(t)
				}
				var store, root string
				var serr, rerr error
				captureStderr(t, func() { store, serr = LocateStoreRoot(); root, rerr = LocateRepoRoot() })
				t.Logf("store=%q serr=%v notInRepo=%v", store, serr, serr != nil && isNotInRepo(serr))
				t.Logf("root=%q rerr=%v", root, rerr)
			})
		}
	}
}

func isNotInRepo(err error) bool {
	for e := err; e != nil; {
		if e == ErrNotInRepo {
			return true
		}
		u, ok := e.(interface{ Unwrap() error })
		if !ok {
			return false
		}
		e = u.Unwrap()
	}
	return false
}

