		}
		return nil
	})
	sort.Strings(res)
	res = append(res, fmt.Sprintf("TOTAL lines=%d rewritten=%d notfixed=%d", n, rewritten, notFixed))
	if err := os.WriteFile(outp, []byte(strings.Join(res, "\n")+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
