	root := os.Getenv("SFH_DATA")
	outPath := os.Getenv("SFH_OUT")
	if root == "" || outPath == "" {
		t.Skip("no corpus")
	}
	var lines []string
	err := filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return err
		}
		ext := strings.ToLower(filepath.Ext(p))
		if ext != ".yaml" && ext != ".yml" && ext != ".json" && ext != ".jsonl" {
			return nil
		}
		if strings.HasPrefix(filepath.Base(p), "audit-") {
			return nil
		}
		data, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(root, p)
		out, gerr := guardWrite(p, data)
		if gerr != nil {
			lines = append(lines, fmt.Sprintf("REFUSE %s: %v", rel, gerr))
			return nil
		}
		again, gerr2 := guardWrite(p, out)
		switch {
		case gerr2 != nil:
			lines = append(lines, fmt.Sprintf("NOTFIX-REFUSE %s: %v", rel, gerr2))
		case !bytes.Equal(again, out):
			lines = append(lines, fmt.Sprintf("NOTFIX-CHANGE %s", rel))
		default:
			lines = append(lines, fmt.Sprintf("OK %s", rel))
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(lines)
	if err := os.WriteFile(outPath, []byte(strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
}

