func TestSFHAuditCorpus(t *testing.T) {
	root := os.Getenv("SFH_DATA")
	outPath := os.Getenv("SFH_OUT")
	if root == "" || outPath == "" {
		t.Skip("no corpus")
	}
	var lines []string
	counts := map[string]int{}
	err := filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return err
		}
		if !strings.HasSuffix(p, ".jsonl") || !strings.HasPrefix(filepath.Base(p), "audit-") {
			return nil
		}
		rel, _ := filepath.Rel(root, p)
		fh, err := os.Open(p)
		if err != nil {
			return err
		}
		defer fh.Close()
		sc := bufio.NewScanner(fh)
		sc.Buffer(nil, 64<<20)
		n := 0
		for sc.Scan() {
			n++
			in := append([]byte(nil), sc.Bytes()...)
			if len(in) == 0 {
				continue
			}
			out, rule := guardAuditLineWhy(in)
			again, rule2 := guardAuditLineWhy(out)
			key := "clean"
			if rule != "" {
				key = "rule:" + rule
			}
			counts[key]++
			if rule != "" {
				lines = append(lines, fmt.Sprintf("RULE %s:%d %s", rel, n, rule))
			}
			if rule2 != "" || string(again) != string(out) {
				lines = append(lines, fmt.Sprintf("NOTFIX %s:%d %q", rel, n, rule2))
			}
		}
		if err := sc.Err(); err != nil {
			lines = append(lines, fmt.Sprintf("READERR %s: %v", rel, err))
		}
		return nil
	})
	if err != nil {
