					}
				case *ast.CallExpr:
					if sel, ok := n.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "SetMapIndex" && len(n.Args) > 0 && callsRenamer(n.Args[0]) {
						bad = append(bad, filepath.ToSlash(path)+":"+fd.Name.Name)
					}
				}
				return true
			})
		}
	}
	sort.Strings(bad)
	return bad
}

func callsRenamer(e ast.Expr) bool {
	found := false
	ast.Inspect(e, func(n ast.Node) bool {
		if c, ok := n.(*ast.CallExpr); ok {
			switch fn := c.Fun.(type) {
			case *ast.Ident:
				found = found || keyRenamers[fn.Name]
			case *ast.SelectorExpr:
				found = found || keyRenamers[fn.Sel.Name]
			}
		}
		return !found
	})
	return found
}

