						hasErr = true
					}
				} else if call, ok := r.(*ast.CallExpr); ok {
					// fmt.Errorf(...) and friends have type error.
					if tv, ok := info.Types[call]; ok && types.Identical(tv.Type, errorType) {
						hasErr = true
					}
				}
			}
			if empty && !hasErr {
				bad = true
			}
		case *ast.AssignStmt:
			for _, r := range v.Rhs {
				if isEmptyString(r) {
					bad = true
				}
			}
		}
		return true
	})
