package mission

import (
	"fmt"
	"math/rand"
	"reflect"
	"sort"
	"strings"
	"testing"

	"github.com/punt-labs/ethos/v4/internal/redact"
)

var probeFrags = []string{"~[redacted-user]", "~[redacted-user]/a", "~[redacted-user]", "~[redacted-user]/a", "~", "~/a", "<repo>", "<repo>/a", "/work/repo", "/work/repo/a",
	"#2", "#3", "a", "token=[redacted-secret]", "[redacted-email]", "[redacted-email]", "[redacted-secret]", "-~-[redacted-slug]", "-~-[redacted-slug]", "/", "#", "2", " ", "A", "~[redacted-user]",
	"password: [redacted-secret]", "[redacted-secret]", "https://u:[redacted-email]/x", "~bob", "[redacted-user]"}

func probeKey(rng *rand.Rand) string {
	n := 1 + rng.Intn(3)
	var b strings.Builder
	for i := 0; i < n; i++ {
		b.WriteString(probeFrags[rng.Intn(len(probeFrags))])
	}
	return b.String()
}

func sortedK(m map[string]any) []string {
	var ks []string
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func TestZZProbeRenameFixedPoint(t *testing.T) {
	t.Setenv("HOME", "~[redacted-user]")
	r, err := NewPathRedactor("/work/repo")
	if err != nil {
		t.Fatal(err)
	}
	passes := map[string]func(string) string{
		"Text": r.Text, "Content": r.Content, "Path": r.Path, "HomePaths": redact.HomePaths, "Prose": redact.Prose,
	}
	rng := rand.New(rand.NewSource(1))
	reported := map[string]int{}
	for name, f := range passes {
		for i := 0; i < 20000; i++ {
			m := map[string]any{}
			for j := 0; j < 2+rng.Intn(4); j++ {
				m[probeKey(rng)] = j
			}
			out, _ := redact.RenameKeys(m, f, false, func(_ string, v any) any { return v })
			if len(out) != len(m) {
				t.Errorf("%s: merged %v -> %v", name, sortedK(m), sortedK(out))
			}
			out2, ren2 := redact.RenameKeys(out, f, false, func(_ string, v any) any { return v })
			if !reflect.DeepEqual(out, out2) {
				if reported[name+"nf"] < 3 {
					t.Errorf("%s: not a fixed point: in %q\n once %q\n twice %q", name, sortedK(m), sortedK(out), sortedK(out2))
				}
				reported[name+"nf"]++
			} else if ren2 {
				if reported[name+"rr"] < 3 {
					t.Errorf("%s: second pass reports a rename though output unchanged: %q", name, sortedK(out))
				}
				reported[name+"rr"]++
			}
		}
	}
	t.Logf("counts %v", reported)
	_ = fmt.Sprint
}

