package hook

import (
	"encoding/json"
	"math/rand"
	"sort"
	"strings"
	"testing"
	"time"
)

var hFrags = []string{"~[redacted-user]", "~[redacted-user]/a", "~[redacted-user]", "~[redacted-user]/a", "~", "~/a", "<repo>", "<repo>/a", "/work/repo", "/work/repo/a",
	"#2", "a", "[redacted-email]", "[redacted-key]", "[redacted-path]", "-~-[redacted-slug]", "-~-[redacted-slug]", "/", "#", "A", "~[redacted-user]", "~bob", "[redacted-user]", "file_path", "Redacted", "TOOL_INPUT"}

func hKey(rng *rand.Rand) string {
	n := 1 + rng.Intn(3)
	var b strings.Builder
	for i := 0; i < n; i++ {
		b.WriteString(hFrags[rng.Intn(len(hFrags))])
	}
	return b.String()
}

func countLeaves(v any) int {
	switch x := v.(type) {
	case map[string]any:
		n := 0
		for _, e := range x {
			n += countLeaves(e)
		}
		return n
	case []any:
		n := 0
		for _, e := range x {
			n += countLeaves(e)
		}
		return n
	}
	return 1
}

func keysOf(m map[string]any) []string {
	var ks []string
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	return ks
}

func TestZZProbeAuditRename(t *testing.T) {
	t.Setenv("HOME", "~[redacted-user]")
	rng := rand.New(rand.NewSource(7))
	bad := map[string]int{}
	for i := 0; i < 20000; i++ {
		ti := map[string]any{}
		for j := 0; j < 1+rng.Intn(4); j++ {
			if rng.Intn(3) == 0 {
				ti[hKey(rng)] = map[string]any{hKey(rng): float64(j), hKey(rng): "v"}
			} else {
				ti[hKey(rng)] = float64(j)
			}
		}
		in := map[string]any{"tool_name": "Bash", "tool_input": ti}
		out, flag := redactToolInput(in, "Bash", "/work/repo")
		if countLeaves(out) != countLeaves(ti) {
			if bad["lost"] < 3 {
				t.Errorf("leaf count changed: %q -> %q", keysOf(ti), keysOf(out))
			}
			bad["lost"]++
		}
		ob, _ := json.Marshal(out)
		ib, _ := json.Marshal(ti)
		if string(ob) != string(ib) && !flag {
			if bad["unflagged"] < 3 {
				t.Errorf("changed without redacted flag: %s -> %s", ib, ob)
			}
			bad["unflagged"]++
		}
		// idempotence of the early pass
		out2, flag2 := redactToolInput(map[string]any{"tool_input": out}, "Bash", "/work/repo")
		ob2, _ := json.Marshal(out2)
		if string(ob2) != string(ob) {
			if bad["nonidem"] < 3 {
				t.Errorf("early pass not idempotent: %s -> %s", ob, ob2)
			}
			bad["nonidem"]++
		} else if flag2 {
			bad["reflag"]++
		}
		// full entry through the guard
		e := buildAuditEntry(in, "s1", "/work/repo", time.Unix(1, 0))
		line, _ := json.Marshal(e)
		g, rule, marker := guardAuditLineFull(line)
		if marker {
			if bad["marker"] < 3 {
				t.Errorf("built entry became a loss marker (%s): %s", rule, line)
			}
			bad["marker"]++
		} else if rule != "" {
			if bad["guardrewrite"] < 3 {
				t.Errorf("guard rewrote a built entry (%s): %s -> %s", rule, line, g)
			}
			bad["guardrewrite"]++
		}
		g2, rule2, _ := guardAuditLineFull(g)
		if string(g2) != string(g) || rule2 != "" {
			if bad["guardnonfix"] < 3 {
				t.Errorf("guard not a fixed point (%s): %s -> %s", rule2, g, g2)
			}
			bad["guardnonfix"]++
		}
	}
	t.Logf("counts %v", bad)
}

