b=s.index('\n}\n',a)+3
new='''func PlanKeys(keys []string, rename func(string) string, foldCase bool) (map[string]string, bool) {
	sorted := append([]string(nil), keys...)
	sort.Strings(sorted)
	canon := func(s string) string { return s }
	if foldCase {
		canon = foldKey
	}
	names := make(map[string]string, len(sorted))
	taken := make(map[string]bool, len(sorted))
	renamedTo := make(map[string]string, len(sorted)) // original -> rename(original)
	for _, k := range sorted {
		nk := rename(k)
		renamedTo[k] = nk
		if nk == k {
			names[k] = k
			taken[canon(k)] = true
		}
	}
	renamed := false
	next := map[string]int{} // base name -> next suffix to try
	for _, k := range sorted {
		nk := renamedTo[k]
		if nk == k {
			continue
		}
		renamed = true
		name := nk
		if taken[canon(name)] {
			n := next[nk]
			if n < 2 {
				n = 2
			}
			for ; taken[canon(fmt.Sprintf("%s#%d", nk, n))]; n++ {
			}
			name = fmt.Sprintf("%s#%d", nk, n)
			next[nk] = n + 1
		}
		names[k] = name
		taken[canon(name)] = true
	}
	return names, renamed
}

// foldKey is a canonical form of s under Unicode simple folding: two strings
// are strings.EqualFold exactly when their foldKeys are equal.
func foldKey(s string) string {
	var b strings.Builder
	for _, r := range s {
		min := r
		for f := unicode.SimpleFold(r); f != r; f = unicode.SimpleFold(f) {
			if f < min {
				min = f
			}
		}
		b.WriteRune(min)
	}
	return b.String()
}

// DuplicateJSONKey scans the tokens of one JSON value for an object that holds
// the same key twice, exactly, at any depth, and returns the path of the first
// such key (name, items[0].name) and the key. A reader keeps the last of two,
// so a record holding a duplicate is not the record it looks like.
func DuplicateJSONKey(data []byte) (path, key string, found bool) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	type frame struct {
		isObj     bool
		seen      map[string]bool
		expectKey bool
		name      string // the key this frame is the value of
		idx       int    // array: index of the next element
	}
	var stack []frame
	pathOf := func(extra string) string {
		p := ""
		for _, f := range stack {
			if f.isObj {
				continue
			}
		}
		for i, f := range stack {
			if i == 0 {
				continue
			}
			parent := stack[i-1]
			switch {
			case parent.isObj:
				if p == "" {
					p = f.name
				} else {
					p += "." + f.name
				}
			default:
				p += fmt.Sprintf("[%d]", f.idx)
			}
		}
		if extra != "" {
			if p == "" {
				return extra
			}
			return p + "." + extra
		}
		return p
	}
	_ = pathOf
	var cur []string // path segments of open containers
	valueDone := func() {
		if n := len(stack); n > 0 {
			if stack[n-1].isObj {
				stack[n-1].expectKey = true
			} else {
				stack[n-1].idx++
			}
		}
	}
	join := func(last string) string {
		out := ""
		for _, seg := range cur {
			if strings.HasPrefix(seg, "[") {
				out += seg
			} else if out == "" {
				out = seg
			} else {
				out += "." + seg
			}
		}
		if last != "" {
			if out == "" {
				return last
			}
			return out + "." + last
		}
		return out
	}
	for {
		tok, err := dec.Token()
		if err != nil {
			return "", "", false
		}
		if d, ok := tok.(json.Delim); ok {
			switch d {
			case '{', '[':
