// writerSeeds are raw audit lines: duplicate keys, invalid UTF-8, surrogate
// escapes, case-variant keys, string tool_input, leaks, and clean lines.
func writerSeeds() [][]byte {
	ts := audit.FormatLineTS(100)
	h := `"ts":"` + ts + `","session":"s"`
