package hook

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

func TestRV21RealAudit(t *testing.T) {
	root := os.Getenv("RV21_DATA")
	outp := os.Getenv("RV21_OUT")
	if root == "" || outp == "" {
		t.Skip()
	}
	var res []string
	n, rewritten, notFixed, migChanged, migErr, migNotFixed := 0, 0, 0, 0, 0, 0
	_ = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(p, ".jsonl") {
			return nil
		}
		data, err := os.ReadFile(p)
		if err != nil {
			t.Fatal(err)
		}
		rel, _ := filepath.Rel(root, p)
		for i, l := range bytes.Split(data, []byte("\n")) {
			if len(bytes.TrimSpace(l)) == 0 {
				continue
			}
			n++
			out, rule := guardAuditLineWhy(l)
			if rule != "" {
				rewritten++
			}
			again, rule2 := guardAuditLineWhy(out)
			if !bytes.Equal(again, out) || rule2 != "" {
				notFixed++
				res = append(res, fmt.Sprintf("NOTFIXED %s:%d %q", rel, i+1, rule2))
			}
			res = append(res, fmt.Sprintf("%s:%d\tG\t%x\t%s", rel, i+1, sha256.Sum256(out), rule))
			// migrate
			mo, merr := redactLegacyLines([]rawAuditLine{{raw: append([]byte(nil), l...)}}, "<repo>")
			if merr != nil {
				migErr++
				res = append(res, fmt.Sprintf("%s:%d\tM\tERR\t%v", rel, i+1, merr))
				continue
			}
			final := guardAuditLine(mo[0].raw)
			ch := !bytes.Equal(mo[0].raw, l)
			if ch {
				migChanged++
			}
			m2, _ := redactLegacyLines([]rawAuditLine{{raw: final}}, "<repo>")
			if m2 == nil || !bytes.Equal(guardAuditLine(m2[0].raw), final) {
				migNotFixed++
				res = append(res, fmt.Sprintf("MIGNOTFIXED %s:%d", rel, i+1))
			}
			res = append(res, fmt.Sprintf("%s:%d\tM\t%x\t%v\t%s", rel, i+1, sha256.Sum256(final), ch, mo[0].key))
		}
		return nil
	})
	sort.Strings(res)
	res = append(res, fmt.Sprintf("TOTAL lines=%d rewritten=%d notfixed=%d migChanged=%d migErr=%d migNotFixed=%d", n, rewritten, notFixed, migChanged, migErr, migNotFixed))
	if err := os.WriteFile(outp, []byte(strings.Join(res, "\n")+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
}

