func probeEvent(t *testing.T, name string, details map[string]any) {
	t.Helper()
	repo := t.TempDir()
	s := NewStoreWithRoots(repo, t.TempDir())
	const id = "m-2026-01-01-001"
	var err error
	errOut := testhelpers.CaptureStderr(t, func() {
		err = s.appendEventLocked(id, Event{TS: "t", Event: "e", Actor: "a", Details: details})
	})
	raw, _ := os.ReadFile(audit.LiveMissionLogPath(repo, id, sessionlessID))
	fmt.Printf("EVENT %s: err=%v\n  stored=%q\n  stderr=%q\n", name, err, raw, errOut)
}

func TestZZProbeEvents(t *testing.T) {
	t.Setenv("HOME", "~[redacted-user]")
	probeEvent(t, "invalid-utf8-value", map[string]any{"x": "a\xffb"})
	probeEvent(t, "invalid-utf8-keys", map[string]any{"a\xff": "1", "a\xfe": "2"})
	probeEvent(t, "invalid-utf8-key-one", map[string]any{"a\xff": "1"})
	probeEvent(t, "surrogate-bytes", map[string]any{"x": "a\xed\xa0\x80b"})
	probeEvent(t, "rename", map[string]any{"~[redacted-user]/a": 1, "~/a": 2})
	probeEvent(t, "case", map[string]any{"A": 1, "a": 2})
	probeEvent(t, "nil", map[string]any{"x": nil})
	probeEvent(t, "secret-key", map[string]any{"[redacted-secret]": 1})
}

func TestZZProbeGuardWrite(t *testing.T) {
	t.Setenv("HOME", "~[redacted-user]")
	cases := []struct{ dest, data string }{
		{"log.jsonl", `{"ts":"t","event":"e","actor":"a","details":{"[redacted-secret]":1,"[redacted-secret]":2}}` + "\n"},
		{"log.jsonl", `{"ts":"t","event":"e","actor":"a","details":{"a":1,"a":2}}` + "\n"},
		{"log.jsonl", "{\"ts\":\"t\",\"event\":\"e\",\"actor\":\"a\",\"details\":{\"k\\nfake: line\":1,\"k\\nfake: line\":2}}\n"},
		{"log.jsonl", `{"ts":"t","event":"e","actor":"a","details":{"x":"𐀀"}}` + "\n"},
		{"log.jsonl", `{"ts":"t","event":"e","actor":"a","details":{"x":null,"y":[null]}}` + "\n"},
		{"log.jsonl", `{"ts":"t","event":"e","actor":"a","details":{"x":1}} {"x":"~[redacted-user]"}` + "\n"},
		{"x.json", `{"a":{"b":1,"b":2}}`},
		{"x.json", `{"a.b":{"c":1},"a":{"b.c":1, "b.c":2}}`},
		{"contract.yaml", "mission_id: m-1\nMission_ID: m-2\n"},
		{"x.yaml", "a: 1\nA: 2\n"},
		{"x.yaml", "a: &x ~[redacted-user] *x\n"},
		{"x.yaml", "a: !!binary L2hvbWUvYm9i/w==\n"},
	}
	for i, c := range cases {
		out, err := guardWrite(filepath.Join("/x", c.dest), []byte(c.data))
		fmt.Printf("GUARD %d %s: err=%v\n  out=%q\n", i, c.dest, err, out)
		if err == nil {
			out2, err2 := guardWrite(filepath.Join("/x", c.dest), out)
			fmt.Printf("  second: same=%v err=%v\n", string(out2) == string(out), err2)
		}
	}
}

func TestZZProbeDelegation(t *testing.T) {
	t.Setenv("HOME", "~[redacted-user]")
	for _, sess := range []string{"a\xffb", "x\ud800", "~[redacted-user]/s", "ok"} {
		repo := t.TempDir()
		var rec string
		var err error
		e := testhelpers.CaptureStderr(t, func() {
			rec, err = WriteDelegationSkeleton(repo, "m-2026-01-01-001", "d-2026-01-01-001", DelegationSkeleton{
				Tier: TierB, AgentType: "bwk", Session: sess, Prompt: []byte("p " + sess),
			})
		})
		body, _ := os.ReadFile(rec)
		prompt, _ := os.ReadFile(filepath.Join(filepath.Dir(rec), "prompt.md"))
		fmt.Printf("DELEG %q: err=%v stderr=%q\n  record=%q\n  prompt=%q\n", sess, err, e, body, prompt)
	}
}

