func TestZZProbeMigrateLines(t *testing.T) {
	t.Setenv("HOME", "~[redacted-user]")
	repo := "~[redacted-user]/repo"
	lines := []string{
		// invalid UTF-8 beside a path the tool_input pass rewrites
		"{\"ts\":\"2026-01-01T00:00:00Z\",\"tool\":\"Bash\",\"tool_input\":{\"command\":\"cat ~[redacted-user]/x\",\"note\":\"a\xffb\"},\"tool_input_hash\":\"h\"}",
		// invalid UTF-8, nothing else to rewrite
		"{\"ts\":\"2026-01-01T00:00:01Z\",\"tool\":\"Bash\",\"tool_input\":{\"note\":\"a\xffb\"},\"tool_input_hash\":\"h\"}",
		// surrogate escape beside a rewritten path
		`{"ts":"2026-01-01T00:00:02Z","tool":"Bash","tool_input":{"command":"cat ~[redacted-user]/x","note":"a\ud800b"},"tool_input_hash":"h"}`,
		// surrogate escape in audit_error (text-swept)
		`{"ts":"2026-01-01T00:00:03Z","audit_error":"cat ~[redacted-user]/x \udc00"}`,
		// duplicate nested key
		`{"ts":"2026-01-01T00:00:04Z","tool":"Bash","tool_input":{"a":"1","a":"~[redacted-user]/x"},"tool_input_hash":"h"}`,
		// case variant inside tool_input with rename collision
		`{"ts":"2026-01-01T00:00:05Z","tool":"Bash","tool_input":{"~[redacted-user]/k":"1","~/k":"2"},"tool_input_hash":"h"}`,
		// clean
		`{"ts":"2026-01-01T00:00:06Z","tool":"Bash","tool_input":{"command":"ls"},"tool_input_hash":"h"}`,
	}
	var in []rawAuditLine
	for _, l := range lines {
		in = append(in, rawAuditLine{raw: []byte(l)})
	}
	var out []rawAuditLine
	var err error
	e := testhelpers.CaptureStderr(t, func() { out, err = redactLegacyLines(in, repo) })
	fmt.Printf("MIGRATE err=%v\nstderr=%s\n", err, e)
	for i, o := range out {
		fmt.Printf("  %d in =%q\n    out=%q\n", i, lines[i], o.raw)
	}
	// second run on own output
	e2 := testhelpers.CaptureStderr(t, func() { out, err = redactLegacyLines(out, repo) })
	fmt.Printf("MIGRATE2 err=%v stderr=%q\n", err, e2)
}

