package hook

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

// A live process holds index.lock, but the index path ethos uses reaches it
// through a symlinked directory: /proc reports the resolved path.
func TestZZProbeHeldLockViaSymlink(t *testing.T) {
	real := t.TempDir()
	link := filepath.Join(t.TempDir(), "link")
	if err := os.Symlink(real, link); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(link, "index")
	if err := os.WriteFile(path, []byte("before"), 0o644); err != nil {
		t.Fatal(err)
	}
	snap, err := snapshotIndex(path)
	if err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	if err := os.WriteFile(path, []byte("after"), 0o644); err != nil {
		t.Fatal(err)
	}
	snap.addFinished(start)

	f, err := os.Create(filepath.Join(real, "index.lock")) // a live holder
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	rerr := snap.restore()
	_, statErr := os.Stat(filepath.Join(real, "index.lock"))
	data, _ := os.ReadFile(path)
	t.Logf("restore err=%v; held lock still present=%v; index=%q", rerr, statErr == nil, data)
}

