package hook

import "github.com/punt-labs/ethos/v4/internal/redact"

// sweepRule is the rule a line breaks when a decoded string or key holds a
// credential or an address. It names the kind, never the value.
const sweepRule = "holds a credential or an address"

// sweepAuditLine returns m with every credential and address removed from its
// decoded strings and keys, and reports whether anything changed. It is the
// sink's check for what the writers' own sweeps did not reach: unknown
// fields, a legacy line, a preview. The path values of tool_input are
// recorded as read, as the writers record them. m is not modified.
func sweepAuditLine(m map[string]any) (map[string]any, bool) {
	changed := false
	out, _ := sweepAuditValue(m, true, false, &changed).(map[string]any)
	return out, changed
}

func sweepAuditValue(v any, top, paths bool, changed *bool) any {
	switch x := v.(type) {
	case string:
		r := sweepGuardString(x)
		if r != x {
			*changed = true
		}
		return r
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			out[i] = sweepAuditValue(e, false, false, changed)
		}
		return out
	case map[string]any:
		out, renamed := redact.RenameKeys(x, func(k string) string {
			if sweepGuardString(k) != k {
				return redactedKey
			}
			return k
		}, top, func(k string, e any) any {
			if s, ok := e.(string); ok && paths && pathKeys[k] {
				return s
			}
			if redact.IsSecretKey(k) {
				if sw, c := redact.SecretsValue(map[string]any{k: e}); c {
					*changed = true
					return sw.(map[string]any)[k]
				}
			}
			return sweepAuditValue(e, false, top && k == "tool_input", changed)
		})
		if renamed {
			*changed = true
		}
		return out
	}
	return v
}

// sweepGuardString removes credentials and addresses from s.
func sweepGuardString(s string) string {
	s = redact.SecretsString(s)
	return redact.EmailPattern.ReplaceAllString(s, redactedEmailToken)
}
