	case ".jsonl":
		for _, line := range strings.Split(string(got), "\\n") {
			var v any
			if strings.TrimSpace(line) == "" {
				continue
			}
			if err := json.Unmarshal([]byte(line), &v); err != nil {
				return "an undecodable line: " + line
			}
			stringsOf(v, &strs, false)
		}
	default:
		strs = []oStr{{v: string(got)}}
	}
	for _, s := range strs {
		if s.holds(home) {
			return s.v
		}
	}
	return ""
}

