func probeLeafDiff(a, b any, path string, out *[]string) {
	switch x := a.(type) {
	case map[string]any:
		y, ok := b.(map[string]any)
		if !ok {
			*out = append(*out, path+" (type)")
			return
		}
		for k, v := range x {
			if _, ok := y[k]; !ok {
				*out = append(*out, path+"/"+k+" (key renamed)")
				continue
			}
			probeLeafDiff(v, y[k], path+"/"+k, out)
		}
	case []any:
		y, _ := b.([]any)
		for i := range x {
			if i < len(y) {
				probeLeafDiff(x[i], y[i], fmt.Sprintf("%s[%d]", path, i), out)
			}
		}
	case string:
		y, _ := b.(string)
		if x != y {
			kind := "secret"
			if redact.SecretsString(x) == x {
				kind = "email"
			}
			// show the matched fragment for local judgement
			frag := ""
			if kind == "email" {
				frag = redact.EmailPattern.FindString(x)
			} else {
				s := redact.SecretsString(x)
				// first differing index
				i := 0
				for i < len(x) && i < len(s) && x[i] == s[i] {
					i++
				}
				st := i - 25
				if st < 0 {
					st = 0
				}
				en := i + 25
				if en > len(x) {
					en = len(x)
				}
				frag = x[st:en]
			}
			*out = append(*out, fmt.Sprintf("%s [%s] %q", path, kind, frag))
		}
	}
}

