package hook

import (
	"bytes"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// captureStderr runs f with os.Stderr redirected and returns what it wrote.
func rv22Capture(t *testing.T, f func()) string {
	tmp, err := os.CreateTemp(os.Getenv("RV22_TMP"), "stderr-*")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(tmp.Name())
	old := os.Stderr
	os.Stderr = tmp
	f()
	os.Stderr = old
	_ = tmp.Close()
	b, _ := os.ReadFile(tmp.Name())
	return string(b)
}

func TestRV22RealAudit(t *testing.T) {
	root := os.Getenv("RV22_DATA")
	outd := os.Getenv("RV22_OUT")
	if root == "" || outd == "" {
		t.Skip()
	}
	repo := "<repo>"
	var summary []string
	n, rewritten, notFixed, migChanged, migErr, migNotFixed := 0, 0, 0, 0, 0, 0
	gNoticeBad, mNoticeBad := 0, 0
	_ = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(p, ".jsonl") {
			return nil
		}
		data, err := os.ReadFile(p)
		if err != nil {
			t.Fatal(err)
		}
		rel, _ := filepath.Rel(root, p)
		var gl, ml, rl []string
		for i, l := range bytes.Split(data, []byte("\n")) {
			if len(bytes.TrimSpace(l)) == 0 {
				continue
			}
			n++
			var out []byte
			stderr := rv22Capture(t, func() { out = guardAuditLine(l) })
			_, rule := guardAuditLineWhy(l)
			notices := strings.Count(stderr, "\n")
			if rule != "" {
				rewritten++
			}
			if (rule != "" && notices != 1) || (rule == "" && notices != 0) {
				gNoticeBad++
				summary = append(summary, fmt.Sprintf("GNOTICE %s:%d rule=%q notices=%d %q", rel, i+1, rule, notices, stderr))
			}
			again, rule2 := guardAuditLineWhy(out)
			if !bytes.Equal(again, out) || rule2 != "" {
				notFixed++
				summary = append(summary, fmt.Sprintf("NOTFIXED %s:%d %q", rel, i+1, rule2))
			}
			gl = append(gl, string(out))
			rl = append(rl, fmt.Sprintf("%d\t%s", i+1, rule))
			var mo []rawAuditLine
			var merr error
			mstderr := rv22Capture(t, func() {
				mo, merr = redactLegacyLines([]rawAuditLine{{raw: append([]byte(nil), l...)}}, repo)
			})
			if merr != nil {
				migErr++
				ml = append(ml, "ERR "+merr.Error())
				continue
			}
			ch := !bytes.Equal(mo[0].raw, l)
			mn := strings.Count(mstderr, "\n")
			if mn > 1 {
				mNoticeBad++
				summary = append(summary, fmt.Sprintf("MNOTICE>1 %s:%d %q", rel, i+1, mstderr))
			}
			if mn == 0 && ch {
				// changed with no notice: only allowed if canonical re-encode only
				summary = append(summary, fmt.Sprintf("MSILENT %s:%d", rel, i+1))
			}
			if ch {
				migChanged++
			}
			final := mo[0].raw
			m2, _ := redactLegacyLines([]rawAuditLine{{raw: final}}, repo)
			if m2 == nil || !bytes.Equal(m2[0].raw, final) {
				migNotFixed++
				summary = append(summary, fmt.Sprintf("MIGNOTFIXED %s:%d", rel, i+1))
			}
			ml = append(ml, string(final))
		}
		for kind, lines := range map[string][]string{"G": gl, "M": ml, "R": rl} {
			dst := filepath.Join(outd, kind, rel)
			_ = os.MkdirAll(filepath.Dir(dst), 0o755)
			if err := os.WriteFile(dst, []byte(strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		return nil
	})
	sort.Strings(summary)
	summary = append(summary, fmt.Sprintf("TOTAL lines=%d rewritten=%d notfixed=%d migChanged=%d migErr=%d migNotFixed=%d gNoticeBad=%d mNoticeBad=%d", n, rewritten, notFixed, migChanged, migErr, migNotFixed, gNoticeBad, mNoticeBad))
	if err := os.WriteFile(filepath.Join(outd, "summary.txt"), []byte(strings.Join(summary, "\n")+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
}

