		}
		if serr != nil {
			sRef++
			lines = append(lines, rel+"\tSCRUB\tERR\t"+serr.Error())
		} else {
			save("SCRUB", rel, so)
			lines = append(lines, fmt.Sprintf("%s\tSCRUB\tOK\t%x", rel, sha256.Sum256(so)))
		}
		var mo []byte
