		} else {
			mo, _, merr = redactYAMLDoc(r.Content, r.Path, artifactType(filepath.Base(rel)), data)
		}
		if merr != nil {
			mRef++
			lines = append(lines, rel+"\tMIGRATE\tERR\t"+merr.Error())
		} else {
			save("MIGRATE", rel, mo)
			lines = append(lines, fmt.Sprintf("%s\tMIGRATE\tOK\t%x", rel, sha256.Sum256(mo)))
		}
		return nil
	})
	sort.Strings(lines)
	lines = append(lines, fmt.Sprintf("TOTAL files=%d guardRefused=%d scrubRefused=%d migrateRefused=%d notfixed=%d", files, refused, sRef, mRef, notFixed))
	if err := os.WriteFile(filepath.Join(outd, "summary.txt"), []byte(strings.Join(lines, "\n")+"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
}

