// Probe: a Network clone whose ssh hangs in connect; after the timeout, is ssh alive?
func TestProbeRV16NetworkTimeoutOrphansSSH(t *testing.T) {
	dir := t.TempDir()
	bin := filepath.Join(dir, "bin")
	if err := os.MkdirAll(bin, 0o755); err != nil {
		t.Fatal(err)
	}
	pidFile := filepath.Join(dir, "ssh.pid")
	ssh := "#!/bin/sh\necho $$ > '" + pidFile + "'\nexec sleep 30 </dev/null\n"
	if err := os.WriteFile(filepath.Join(bin, "ssh"), []byte(ssh), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", bin+":"+os.Getenv("PATH"))
	t.Setenv("HOME", dir)
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	start := time.Now()
	_, err := Run(Spec{Git: "git", Args: []string{"clone", "ssh://example.invalid/x.git", filepath.Join(dir, "c")}, Dir: dir, Network: true, Limit: time.Second})
	t.Logf("err=%v after %v", err, time.Since(start))
	time.Sleep(500 * time.Millisecond)
	data, rerr := os.ReadFile(pidFile)
	if rerr != nil {
		t.Fatalf("ssh never ran: %v", rerr)
	}
	pid, _ := strconv.Atoi(strings.TrimSpace(string(data)))
	alive := syscall.Kill(pid, 0) == nil
	t.Logf("ssh pid %d alive after timeout: %v", pid, alive)
	_ = syscall.Kill(pid, syscall.SIGKILL)
	if _, err := os.Stat(filepath.Join(dir, "c")); err == nil {
		t.Logf("partial clone dir left: %s", filepath.Join(dir, "c"))
	}
}

