// Package zzmutant holds probe mutants for the tripwire tests. Not shipped.
package zzmutant

import (
	"os/exec"

	"github.com/punt-labs/ethos/v4/internal/resolve"
)

// A turns CheckoutErr into "" by testing the field directly.
func A() string {
	l := resolve.Roots()
	if l.CheckoutErr != nil {
		return ""
	}
	return l.Checkout
}

// B reads Config without ever looking at ConfigErr.
func B() bool {
	l := resolve.Roots()
	return l.Config == nil
}

// C mentions StoreErr only to discard it.
func C() string {
	l := resolve.Roots()
	_ = l.StoreErr
	return l.Store
}

// D turns Err() into "".
func D() string {
	l := resolve.Roots()
	if err := l.Err(); err != nil {
		return ""
	}
	return l.Store
}

// E hands the whole Located to a helper that drops the error.
func E() string { return e2(resolve.Roots()) }

func e2(l resolve.Located) string {
	if l.StoreErr != nil {
		l.Store = ""
	}
	return l.Store
}

