import json
import os
import sys
from collections import Counter

data, base, head = sys.argv[1], sys.argv[2], sys.argv[3]


def leaves(v, path, out):
    if isinstance(v, dict):
        for k, e in v.items():
            out.append((path + "/k", k))
            leaves(e, path + "/" + k, out)
    elif isinstance(v, list):
        for i, e in enumerate(v):
            leaves(e, path + "[]", out)
    else:
        out.append((path, v))


def classify(old, new):
    if not isinstance(new, str):
        return "type:" + type(new).__name__
    kinds = []
    for tok in ("[redacted-email]", "[redacted-secret]", "[redacted-path]", "[redacted]", "[redacted-key]"):
        if tok in new and (not isinstance(old, str) or tok not in old):
            kinds.append(tok)
    return ",".join(kinds) or "other"


def load(p):
    with open(p, encoding="utf-8", errors="surrogateescape") as f:
        return f.read().split("\n")


gdiff = Counter()
gdet = []
msilent = Counter()
msil_det = []
for dp, _, fs in os.walk(data):
    for fn in fs:
        if not fn.endswith(".jsonl"):
            continue
        p = os.path.join(dp, fn)
        rel = os.path.relpath(p, data)
        raw = [l for l in load(p)]
        idx = [i + 1 for i, l in enumerate(raw) if l.strip()]
        bG = load(os.path.join(base, "G", rel))
        hG = load(os.path.join(head, "G", rel))
        hM = load(os.path.join(head, "M", rel))
        for j, n in enumerate(idx):
            b, h = bG[j], hG[j]
            if b != h:
                try:
                    bj, hj = json.loads(b), json.loads(h)
                except Exception as e:
                    gdet.append((rel, n, "undecodable", str(e)))
                    continue
                bl, hl = Counter(map(repr, leaves(bj, "", []) and [])), None
                bL, hL = [], []
                leaves(bj, "", bL)
                leaves(hj, "", hL)
                bd = dict()
                for pth, v in bL:
                    bd.setdefault(pth, []).append(v)
                hd = dict()
                for pth, v in hL:
                    hd.setdefault(pth, []).append(v)
                kinds = set()
                fields = set()
                for pth in set(bd) | set(hd):
                    bv, hv = bd.get(pth, []), hd.get(pth, [])
                    if bv != hv:
                        for x, y in zip(bv + [None] * len(hv), hv + [None] * len(bv)):
                            if x != y:
                                if pth in ("/tool_input_hash", "/redacted"):
                                    continue
                                kinds.add(classify(x, y))
                                fields.add(pth)
                gdiff[",".join(sorted(kinds))] += 1
                gdet.append((rel, n, ",".join(sorted(kinds)), ",".join(sorted(fields))))
            # migrate silent value change
            m = hM[j]
            if m.startswith("ERR "):
                continue
            try:
                inj = json.loads(raw[n - 1])
                outj = json.loads(m)
            except Exception:
                continue
            if inj != outj:
                d = {k for k in set(inj) | set(outj) if inj.get(k) != outj.get(k)}
                msil_det.append((rel, n, ",".join(sorted(d))))

print("G differences by kind:", dict(gdiff))
for r in sorted(gdet):
