func indexLeaks(t *testing.T, repo string) string {
	t.Helper()
	cmd := exec.Command("git", "grep", "--cached", "-l", "~[redacted-user]")
	cmd.Dir = repo
	out, _ := cmd.Output()
	return strings.TrimSpace(string(out))
}

func listDir(t *testing.T, dir string) []string {
	es, _ := os.ReadDir(dir)
	var n []string
	for _, e := range es {
		n = append(n, e.Name())
	}
	sort.Strings(n)
	return n
}

func report(t *testing.T, repo, sealedDir string) {
	t.Logf("sealed: %v", listDir(t, sealedDir))
	t.Logf("local: %v", listDir(t, QuarantineDir(repo)))
	t.Logf("index: %s", gitOut(t, repo, "ls-files", "-s"))
