package hook

import (
	"bytes"
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func captureStderr(t *testing.T, f func()) string {
	t.Helper()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	old := os.Stderr
	os.Stderr = w
	done := make(chan string)
	go func() {
		b, _ := io.ReadAll(r)
		done <- string(b)
	}()
	f()
	w.Close()
	os.Stderr = old
	return <-done
}

func runAppend(t *testing.T, repo string, ti any, tool string) (string, string) {
	t.Helper()
	in := map[string]any{"session_id": "s1", "tool_name": tool, "tool_input": ti}
	data, _ := json.Marshal(in)
	out := captureStderr(t, func() {
		_ = HandleAuditLog(bytes.NewReader(data), repo, filepath.Join(repo, "global"))
	})
	live := filepath.Join(repo, ".punt-labs", "local", "ethos", "sessions", "s1.audit.jsonl")
	b, _ := os.ReadFile(live)
	return out, string(b)
}

func TestProbeAppender(t *testing.T) {
	home, _ := os.UserHomeDir()
	t.Setenv("DELEGATION_ID", "x")
	t.Setenv("MISSION_ID", "m")
	cases := []struct {
		name string
		ti   any
		tool string
	}{
		{"clean", map[string]any{"command": "ls"}, "Bash"},
		{"ownhome", map[string]any{"command": "cat " + home + "/x"}, "Bash"},
		{"foreignhome", map[string]any{"command": "cat ~[redacted-user]/x"}, "Bash"},
		{"filepath-own", map[string]any{"file_path": home + "/x"}, "Read"},
		{"key-home", map[string]any{"~[redacted-user]/k": "v"}, "Bash"},
		{"secretkey", map[string]any{"api_token": "[redacted-secret]"}, "Bash"},
		{"placeholderkey", map[string]any{"[redacted-secret]": "abc"}, "Bash"},
		{"email", map[string]any{"to": "[redacted-email]", "body": "hi"}, "mcp__plugin_beadle_email__send_email"},
		{"toolhome", map[string]any{"command": "ls"}, "~[redacted-user]/tool"},
		{"nonmap", "plain ~[redacted-user]/x", "Bash"},
		{"dupcase", map[string]any{"Command": "a", "command": "b"}, "Bash"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			repo := t.TempDir()
			errOut, file := runAppend(t, repo, c.ti, c.tool)
			n := strings.Count(errOut, "\n")
			t.Logf("stderr(%d lines): %s", n, errOut)
			t.Logf("file: %s", file)
			if strings.Contains(file, "/home/") {
				t.Errorf("home in live file")
			}
		})
	}
}

// Write fails: the live file is a directory.
func TestProbeAppenderWriteFails(t *testing.T) {
	home, _ := os.UserHomeDir()
	repo := t.TempDir()
	live := filepath.Join(repo, ".punt-labs", "local", "ethos", "sessions", "s1.audit.jsonl")
	if err := os.MkdirAll(live, 0o700); err != nil {
		t.Fatal(err)
	}
	errOut, _ := runAppend(t, repo, map[string]any{"command": "cat " + home + "/x"}, "Bash")
	t.Logf("stderr: %s", errOut)
	if strings.Contains(errOut, "was rewritten before it was stored") {
		t.Errorf("notice for a failed write")
	}
}

