// restageIfDifferent stages path when the index holds something other than
// its work-tree bytes b. An index blob that fails check is saved first.
func restageIfDifferent(repoRoot, path string, b []byte, stem string, check func([]byte) string) error {
	blob, tracked, err := IndexBlob(repoRoot, path)
	if err != nil {
		return err
	}
	if !tracked || bytes.Equal(blob, b) {
