// record is staged, and no second .corrupt-<hash> is made for it.
func finishRecordedRetirement(repoRoot, sealedDir string, cn ChunkName, chunkPath string) (bool, error) {
	b, err := os.ReadFile(chunkPath)
	if err != nil {
		return false, fmt.Errorf("reading %s: %w", chunkPath, err)
	}
	sum := sha256.Sum256(b)
	want := hex.EncodeToString(sum[:])
	entries, err := os.ReadDir(sealedDir)
