ACTION: wait | ctrlc | hup | type | term | quit
"""
import os, pty, sys, time, select, signal

S = "<repo>/.tmp/sfh18-classes"
action, delay = sys.argv[1], float(sys.argv[2])
cmd = sys.argv[sys.argv.index("--") + 1:]
P = S + "/tmp/fakessh"
for f in ("ssh.pid", "child.pid", "args"):
    try: os.unlink(os.path.join(P, f))
    except FileNotFoundError: pass

pid, fd = pty.fork()
if pid == 0:
    os.execvp(cmd[0], cmd)

buf = b""
t0 = time.time()
def pump(until):
    global buf
    while time.time() < until:
        r, _, _ = select.select([fd], [], [], 0.1)
        if r:
            try:
                d = os.read(fd, 4096)
            except OSError:
                return False
            if not d:
                return False
            buf += d
        wp, st = os.waitpid(pid, os.WNOHANG)
        if wp:
            return ("exit", st)
    return True

res = pump(t0 + delay)
acted = time.time()
if res is True:
    if action == "ctrlc": os.write(fd, b"\x03")
    elif action == "quit": os.write(fd, b"\x1c")
    elif action == "type": os.write(fd, b"secret\n")
    elif action == "term": os.kill(pid, signal.SIGTERM)
    elif action == "hup": os.close(fd); fd = None
if fd is not None:
    res = pump(time.time() + 20)
else:
    for _ in range(200):
        wp, st = os.waitpid(pid, os.WNOHANG)
        if wp: res = ("exit", st); break
        time.sleep(0.1)
done = time.time()
print("OUTPUT>>>", buf.decode(errors="replace"))
print("RESULT", res, "action", action, "elapsed_after_action %.1f" % (done - acted))
time.sleep(2.5)
for f in ("ssh.pid", "child.pid"):
    try:
        p = int(open(os.path.join(P, f)).read())
        try:
            os.kill(p, 0); alive = "ALIVE"
            os.kill(p, signal.SIGKILL)
        except ProcessLookupError: alive = "dead"
        print(f, p, alive)
    except FileNotFoundError:
        print(f, "none")
try: print(open(os.path.join(P, "args")).read())
except FileNotFoundError: pass

