"""Drive `ethos serve` over stdio. usage: mcp.py ETHOS 'tool:json-args' ..."""
import json, subprocess, sys

proc = subprocess.Popen([sys.argv[1], "serve"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
def send(obj):
    proc.stdin.write(json.dumps(obj) + "\n"); proc.stdin.flush()
def recv(want_id):
    while True:
        line = proc.stdout.readline()
        if not line:
            return None
        m = json.loads(line)
        if m.get("id") == want_id:
            return m
send({"jsonrpc": "2.0", "id": 0, "method": "initialize", "params": {"protocolVersion": "2025-06-18", "capabilities": {}, "clientInfo": {"name": "p", "version": "0"}}})
init = recv(0)
if init is None:
    print("serve died:", proc.stderr.read()); sys.exit(1)
send({"jsonrpc": "2.0", "method": "notifications/initialized"})
for i, spec in enumerate(sys.argv[2:], 1):
    tool, _, args = spec.partition(":")
    send({"jsonrpc": "2.0", "id": i, "method": "tools/call", "params": {"name": tool, "arguments": json.loads(args or "{}")}})
    r = recv(i)
    if r is None:
        print(spec, "-> no response"); break
    if "error" in r:
        print(spec, "-> RPCERR", r["error"]); continue
    res = r["result"]
    texts = [c.get("text", "") for c in res.get("content", [])]
    print("==", spec, "isError=%s" % res.get("isError", False))
    for t in texts:
        print("   ", t[:900].replace("\n", "\n    "))
proc.stdin.close()
try:
    proc.wait(5)
except subprocess.TimeoutExpired:
    proc.kill()
err = proc.stderr.read()
if err.strip():
    print("serve stderr:", err[:1500])

