// TestSFHDataDump guards every jsonl line under SFH_DATA and writes one row
// per line to SFH_OUT: file, line, rule, marker, sha of output.
func TestSFHDataDump(t *testing.T) {
	root := os.Getenv("SFH_DATA")
	outp := os.Getenv("SFH_OUT")
	if root == "" || outp == "" {
		t.Skip("no SFH_DATA")
	}
	var files []string
	_ = filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err == nil && !info.IsDir() && (strings.HasSuffix(p, ".jsonl") || strings.Contains(p, ".jsonl.corrupt")) {
			files = append(files, p)
		}
		return nil
	})
	sort.Strings(files)
	var buf bytes.Buffer
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		rel, _ := filepath.Rel(root, f)
		sc := bufio.NewScanner(bytes.NewReader(data))
		sc.Buffer(make([]byte, 64<<20), 64<<20)
		n := 0
		for sc.Scan() {
			n++
			l := append([]byte(nil), sc.Bytes()...)
			if len(bytes.TrimSpace(l)) == 0 {
				continue
			}
			out, rule, marker := guardAuditLineFull(l)
			sum := sha256.Sum256(out)
			same := bytes.Equal(out, l)
			fmt.Fprintf(&buf, "%s:%d\tmarker=%v\tsame=%v\trule=%q\tout=%s\n", rel, n, marker, same, rule, hex.EncodeToString(sum[:8]))
			// idempotence: guard the output again
			out2, rule2, marker2 := guardAuditLineFull(out)
			if !bytes.Equal(out2, out) || rule2 != "" || marker2 {
				fmt.Fprintf(&buf, "NONIDEMPOTENT %s:%d rule2=%q marker2=%v\n", rel, n, rule2, marker2)
			}
		}
	}
	if err := os.WriteFile(outp, buf.Bytes(), 0o600); err != nil {
		t.Fatal(err)
	}
}

package mission

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// TestSFHGuardDump runs guardWrite over every yaml/json/jsonl/md file under
// SFH_DATA (skipping sessions/ audit chunks) and writes one row per file.
func TestSFHGuardDump(t *testing.T) {
	root := os.Getenv("SFH_DATA")
	outp := os.Getenv("SFH_OUT")
	if root == "" || outp == "" {
		t.Skip("no SFH_DATA")
	}
	var files []string
	_ = filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		ext := filepath.Ext(p)
		switch ext {
		case ".yaml", ".yml", ".json", ".jsonl", ".md":
			files = append(files, p)
		}
		return nil
	})
	sort.Strings(files)
	var buf bytes.Buffer
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		rel, _ := filepath.Rel(root, f)
		out, gErr := guardWrite(f, data)
		if gErr != nil {
			msg := strings.ReplaceAll(gErr.Error(), "\n", " ")
			fmt.Fprintf(&buf, "%s\tREFUSED\t%s\n", rel, msg)
			continue
		}
		sum := sha256.Sum256(out)
		fmt.Fprintf(&buf, "%s\tok\tsame=%v\t%s\n", rel, bytes.Equal(out, data), hex.EncodeToString(sum[:8]))
		// second pass on output: must accept and be a fixed point
		out2, e2 := guardWrite(f, out)
		if e2 != nil {
			fmt.Fprintf(&buf, "SECONDPASS-REFUSED %s %s\n", rel, e2)
		} else if !bytes.Equal(out2, out) {
			fmt.Fprintf(&buf, "SECONDPASS-CHANGED %s\n", rel)
		}
	}
	if err := os.WriteFile(outp, buf.Bytes(), 0o600); err != nil {
		t.Fatal(err)
	}
}

