package mission

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// TestSFHScrubDump: SFH_REPO is a repo root holding .punt-labs/ethos; dry-run
// scrub over every scrubbable file, then the event record pass + sink over
// every Event line in log.jsonl files and mission live logs.
func TestSFHScrubDump(t *testing.T) {
	repo := os.Getenv("SFH_REPO")
	outp := os.Getenv("SFH_OUT")
	if repo == "" {
		t.Skip()
	}
	var rels []string
	_ = filepath.Walk(filepath.Join(repo, ".punt-labs", "ethos"), func(p string, info os.FileInfo, err error) error {
		if err == nil && !info.IsDir() {
			rel, _ := filepath.Rel(repo, p)
			rels = append(rels, filepath.ToSlash(rel))
		}
		return nil
	})
	sort.Strings(rels)
	var buf bytes.Buffer
	res, err := ScrubFiles(repo, os.Getenv("SFH_GLOBAL"), rels, true)
	for _, c := range res.Changed {
		fmt.Fprintf(&buf, "SCRUB-CHANGED %s\n", c)
	}
	if err != nil {
		for _, l := range strings.Split(err.Error(), "\n") {
			fmt.Fprintf(&buf, "SCRUB-ERR %s\n", l)
		}
	}
	// events
	var logs []string
	_ = filepath.Walk(repo, func(p string, info os.FileInfo, err error) error {
		if err == nil && !info.IsDir() && strings.HasSuffix(p, ".jsonl") && strings.Contains(p, "missions") && !strings.HasSuffix(p, "missions.jsonl") {
			logs = append(logs, p)
		}
		return nil
	})
	sort.Strings(logs)
	for _, f := range logs {
		data, _ := os.ReadFile(f)
		rel, _ := filepath.Rel(repo, f)
		sc := bufio.NewScanner(bytes.NewReader(data))
		sc.Buffer(make([]byte, 64<<20), 64<<20)
		n := 0
		for sc.Scan() {
			n++
			var e Event
			if json.Unmarshal(sc.Bytes(), &e) != nil {
				fmt.Fprintf(&buf, "EV %s:%d undecodable\n", rel, n)
				continue
			}
			r, rerr := RedactRecord(repo, e)
			if rerr != nil {
				fmt.Fprintf(&buf, "EV %s:%d REDACT-ERR %v\n", rel, n, rerr)
				continue
			}
			b, _ := json.Marshal(r)
			out, gerr := guardWrite(filepath.Join(repo, "log.jsonl"), append(b, '\n'))
			if gerr != nil {
				fmt.Fprintf(&buf, "EV %s:%d REFUSED %v\n", rel, n, gerr)
				continue
			}
			sum := sha256.Sum256(out)
			fmt.Fprintf(&buf, "EV %s:%d ok %s\n", rel, n, hex.EncodeToString(sum[:8]))
		}
	}
	_ = os.WriteFile(outp, buf.Bytes(), 0o600)
}

