package audit

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/punt-labs/ethos/v4/internal/redact"
)

func captureStderr(t *testing.T, fn func()) string {
	t.Helper()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	old := os.Stderr
	os.Stderr = w
	done := make(chan string)
	go func() {
		b, _ := io.ReadAll(r)
		done <- string(b)
	}()
	fn()
	os.Stderr = old
	w.Close()
	return <-done
}

func listDir(t *testing.T, d string) []string {
	es, _ := os.ReadDir(d)
	var n []string
	for _, e := range es {
		n = append(n, e.Name())
	}
	return n
}

// P1: marker present; the .corrupt work tree is clean but the index holds a
// leak (older binary's git mv then a later clean record). git add fails
// (index.lock). Does the run print "was withheld" though the index still
// holds the leak?
func TestSFH_P1_RestageNoticeBeforeFailedAdd(t *testing.T) {
	repo, sealedDir, live, name, cn := quarantineSetup(t, true)
	rel := filepath.Join("sealed", name+".corrupt")
	gitOut(t, repo, "mv", "--", filepath.Join("sealed", name), rel)
	body := leakyChunkBody()
	if err := writeRecord(filepath.Join(repo, rel), body, "names another user's home"); err != nil {
		t.Fatal(err)
	}
	// a marker so the marker path runs
	if err := writeMarkerAtomic(sealedDir, cn.MarkerFile(), Marker{Chunk: cn.Stem(), VerifiedLast: 300, Reason: "x"}); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(repo, ".git", "index.lock"), nil, 0o600); err != nil {
		t.Fatal(err)
	}
	var qerr error
	out := captureStderr(t, func() {
		_, qerr = Quarantine(repo, sealedDir, cn, live, "ts mismatch", redact.Prose, keepLine, homeCheck)
	})
	os.Remove(filepath.Join(repo, ".git", "index.lock"))
	staged := gitOut(t, repo, "show", ":"+rel)
	t.Logf("err=%v", qerr)
	t.Logf("stderr=%q", out)
	t.Logf("index still leaks: %v", strings.Contains(staged, "~[redacted-user]"))
}

// P1b: same state, no marker (resume path).
func TestSFH_P1b_RestageNoticeBeforeFailedAddResume(t *testing.T) {
	repo, sealedDir, live, name, cn := quarantineSetup(t, true)
	rel := filepath.Join("sealed", name+".corrupt")
	gitOut(t, repo, "mv", "--", filepath.Join("sealed", name), rel)
	body := leakyChunkBody()
	if err := writeRecord(filepath.Join(repo, rel), body, "names another user's home"); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(repo, ".git", "index.lock"), nil, 0o600); err != nil {
		t.Fatal(err)
