func sfhCopyTree(t *testing.T, src, dst string) {
	t.Helper()
	err := filepath.Walk(src, func(p string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, p)
		d := filepath.Join(dst, rel)
		if info.IsDir() {
			return os.MkdirAll(d, 0o700)
		}
		if !info.Mode().IsRegular() {
			return nil
		}
		in, err := os.Open(p)
		if err != nil {
			return err
		}
		defer in.Close()
		out, err := os.OpenFile(d, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, info.Mode().Perm()|0o600)
		if err != nil {
			return err
		}
		defer out.Close()
		_, err = io.Copy(out, in)
		return err
	})
	if err != nil {
		t.Fatal(err)
	}
}

// TestSFHMigrateDump: SFH_REPO (repo root with .punt-labs/ethos) and
// SFH_GLOBAL (legacy *.audit.jsonl) are copied; migrate runs dry then real;
// SFH_OUT gets stdout, stderr and a hash of every sessions/*/audit.jsonl and
// each remaining legacy file.
func TestSFHMigrateDump(t *testing.T) {
	repoSrc, globSrc, outp := os.Getenv("SFH_REPO"), os.Getenv("SFH_GLOBAL"), os.Getenv("SFH_OUT")
	if repoSrc == "" {
		t.Skip()
	}
	work := t.TempDir()
	repo := filepath.Join(work, "repo")
	glob := filepath.Join(work, "global")
	sfhCopyTree(t, filepath.Join(repoSrc, ".punt-labs", "ethos"), filepath.Join(repo, ".punt-labs", "ethos"))
	sfhCopyTree(t, globSrc, glob)
	var buf bytes.Buffer
	for _, dry := range []bool{true, false, false} {
		var out bytes.Buffer
		var err error
		notice := testhelpers.CaptureStderr(t, func() { err = MigrateAudit(glob, repo, dry, &out) })
		fmt.Fprintf(&buf, "=== dry=%v err=%v\n--- stdout\n%s--- stderr\n%s", dry, err, out.String(), strings.ReplaceAll(notice, work, "<WORK>"))
	}
	var files []string
	_ = filepath.Walk(repo, func(p string, info os.FileInfo, err error) error {
		if err == nil && !info.IsDir() && filepath.Base(p) == "audit.jsonl" {
			files = append(files, p)
		}
		return nil
	})
	sort.Strings(files)
	for _, f := range files {
		b, _ := os.ReadFile(f)
		sum := sha256.Sum256(b)
		rel, _ := filepath.Rel(repo, f)
		fmt.Fprintf(&buf, "FILE %s lines=%d %s\n", rel, bytes.Count(b, []byte("\n")), hex.EncodeToString(sum[:8]))
	}
	rem, _ := os.ReadDir(glob)
	for _, e := range rem {
		fmt.Fprintf(&buf, "LEGACY-LEFT %s\n", e.Name())
	}
	_ = os.WriteFile(outp, buf.Bytes(), 0o600)
}

