#!/bin/bash
# .git shape probes: head vs main, CLI / hook / serve / doctor.
. ~/Coding/punt-labs/.tmp/sfh22-classes/probes/lib.sh
H=$(mkhome dg)
SERVE_IN='{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"p","version":"1"}}}
{"jsonrpc":"2.0","method":"notifications/initialized"}
{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"identity","arguments":{"method":"get","handle":"dup"}}}
{"jsonrpc":"2.0","id":3,"method":"tools/call","params":{"name":"identity","arguments":{"method":"list"}}}'

probe() { # probe LABEL DIR
  local label=$1 d=$2
  for bin in ethos-main ethos-head; do
    echo "===== $label :: $bin"
    echo "--- git rev-parse:"; (cd "$d" && env -i HOME=$H PATH=$PATH GIT_CEILING_DIRECTORIES=$SB GIT_CONFIG_NOSYSTEM=1 LANG=C git rev-parse --show-toplevel 2>&1 | head -3)
    echo "--- identity get dup:"; run $bin $H "$d" identity get dup 2>&1 | head -6
    echo "--- identity list:"; run $bin $H "$d" identity list 2>&1 | head -8
    echo "--- whoami:"; run $bin $H "$d" whoami 2>&1 | head -4
    echo "--- doctor:"; run $bin $H "$d" doctor 2>&1 | grep -iv '^ *$' | head -30
    echo "--- hook session-start:"; printf '{"session_id":"s-%s","cwd":"%s","hook_event_name":"SessionStart"}' "$label" "$d" | run $bin $H "$d" hook session-start 2>&1 | cut -c1-600 | head -8
    echo "--- serve:"; printf '%s\n' "$SERVE_IN" | EXTRA_ENV= timeout 10 bash -c ". $SB/probes/lib.sh; run $bin $H '$d' serve" 2>&1 | grep -v '"id":1' | cut -c1-500 | head -8
  done
}

shape() { # shape NAME MUTATION(path relative to .git, mode) ; uses nested option
  local name=$1 rel=$2 mode=$3
  local r=$P/dg-$name
  mkrepo $r
  local target=$r/.git/$rel
  [ -z "$rel" ] && target=$r/.git
  chmod $mode "$target"
  probe "$name" "$r"
  chmod 755 "$target" 2>/dev/null
}

case "${1:-all}" in
  base) mkrepo $P/dg-base; probe base $P/dg-base ;;
  head000) shape head000 HEAD 000 ;;
  objects000) shape objects000 objects 000 ;;
  refs000) shape refs000 refs 000 ;;
  git300) shape git300 "" 300 ;;
  git500) shape git500 "" 500 ;;
  git000) shape git000 "" 000 ;;
  nohead) mkrepo $P/dg-nohead; mv $P/dg-nohead/.git/HEAD $P/dg-nohead/.git/HEAD.moved; probe nohead $P/dg-nohead ;;
  gitfile000)
    r=$P/dg-gitfile; mkrepo $r; mv $r/.git $P/dg-gitfile-store; echo "gitdir: $P/dg-gitfile-store" > $r/.git; chmod 000 $r/.git
    probe gitfile000 $r; chmod 644 $r/.git ;;
  nested)
    o=$P/dg-outer; mkrepo $o; i=$o/inner; mkdir -p $i; gitc $i init -q .
    mkdir -p $i/.punt-labs/ethos/identities
    printf 'name: Inner Dup\nhandle: dup\nkind: human\n' > $i/.punt-labs/ethos/identities/dup.yaml
