# Other .git shapes: head vs main, identity get dup (repo vs global vs refusal).
. ~/Coding/punt-labs/.tmp/sfh22-classes/probes/lib.sh
shape() {
  local name=$1
  for bin in ethos-main ethos-head; do
    H=$(mkhome misc-$bin)
    r=$P/misc-$name-$bin; mkrepo $r
    case $name in
      dangling) rm -rf $r/.git; ln -s $P/nowhere $r/.git ;;
      gitfile-missing) rm -rf $r/.git; echo "gitdir: $P/nowhere" > $r/.git ;;
      gitfile-garbage) rm -rf $r/.git; echo "hello" > $r/.git ;;
      gitfile-empty) rm -rf $r/.git; : > $r/.git ;;
      fifo) rm -rf $r/.git; mkfifo $r/.git ;;
      objects-missing) rm -rf $r/.git/objects ;;
      refs-file) rm -rf $r/.git/refs; echo x > $r/.git/refs ;;
      head-dir) rm -f $r/.git/HEAD; mkdir $r/.git/HEAD ;;
      head-symlink-unborn) rm -f $r/.git/HEAD; ln -s refs/heads/master $r/.git/HEAD ;;
      subdir) mkdir -p $r/sub/deeper; r=$r/sub/deeper; : > $P/misc-$name-$bin/.git/HEAD ;;
    esac
    printf '%-20s %-10s git: %-40s ethos: ' $name $bin "$(cd $r && env -i HOME=$H PATH=$PATH GIT_CEILING_DIRECTORIES=$SB GIT_CONFIG_NOSYSTEM=1 LANG=C timeout 5 git rev-parse --show-toplevel 2>&1 | head -1 | cut -c1-40)"
    run $bin $H $r identity get dup 2>&1 | grep -v UnderClaude | grep -o 'Repo Dup\|Global Dup\|^ethos: .\{0,160\}\|\[exit [0-9]*\]' | tr '\n' ' '; echo
  done
}
for s in dangling gitfile-missing gitfile-garbage gitfile-empty fifo objects-missing refs-file head-dir head-symlink-unborn subdir; do shape $s; done

