    objects-missing) mkdir "$d" "$d/refs"; echo 'ref: refs/heads/main' > "$d/HEAD";;
    objects-unsearchable) mkdir "$d" "$d/objects" "$d/refs"; echo 'ref: refs/heads/main' > "$d/HEAD"; chmod 000 "$d/objects";;
    refs-file) mkdir "$d" "$d/objects"; echo 'ref: refs/heads/main' > "$d/HEAD"; : > "$d/refs";;
