func TestZZProbeShapeCount(t *testing.T) {
	t.Logf("len(gitShapes)=%d", len(gitShapes))
	for n := range gitShapes {
		t.Logf("shape: %s", n)
	}
}

// HEAD is a symlink to a non-refs/ file that holds a valid ref.
func TestZZProbeHeadSymlinkElsewhereValid(t *testing.T) {
	for _, withGit := range []bool{true, false} {
		dir := filepath.Join(t.TempDir(), "d")
		dot := filepath.Join(dir, ".git")
		for _, d := range []string{"objects", "refs/heads"} {
			if err := os.MkdirAll(filepath.Join(dot, d), 0o755); err != nil {
				t.Fatal(err)
			}
		}
		if err := os.WriteFile(filepath.Join(dot, "headfile"), []byte("ref: refs/heads/main\n"), 0o644); err != nil {
			t.Fatal(err)
		}
		if err := os.Symlink("headfile", filepath.Join(dot, "HEAD")); err != nil {
			t.Fatal(err)
		}
		t.Setenv("GIT_CEILING_DIRECTORIES", filepath.Dir(dir))
		t.Chdir(dir)
		out, gerr := exec.Command("git", "rev-parse", "--show-toplevel").CombinedOutput()
		t.Logf("withGit=%v git rev-parse: %q err=%v", withGit, out, gerr)
		if !withGit {
			t.Setenv("PATH", t.TempDir())
		}
		got, err := captureLocate(t)
		t.Logf("withGit=%v locateRepoRoot: got=%q err=%v notInRepo=%v", withGit, got, err, err != nil && errorsIsNotInRepo(err))
	}
}

func errorsIsNotInRepo(err error) bool {
	for e := err; e != nil; {
		if e == ErrNotInRepo {
			return true
		}
		u, ok := e.(interface{ Unwrap() error })
		if !ok {
			return false
		}
		e = u.Unwrap()
	}
	return false
}

// A .git above a (simulated) filesystem boundary, below the ceiling, hand rules.
func TestZZProbeMountBoundary(t *testing.T) {
	outer := t.TempDir()
	testhelpers.MakeGitDir(t, outer)
	inner := filepath.Join(outer, "mnt")
	if err := os.Mkdir(inner, 0o755); err != nil {
		t.Fatal(err)
	}
	realInner, _ := filepath.EvalSymlinks(inner)
	old := gitenv.SetDeviceOf(func(p string) (uint64, bool) {
		if p == realInner {
			return 2, true
		}
		return 1, true
	})
	t.Cleanup(func() { gitenv.SetDeviceOf(old) })
	t.Setenv("GIT_CEILING_DIRECTORIES", filepath.Dir(outer))
	t.Chdir(inner)
	t.Setenv("PATH", t.TempDir())
	got, err := captureLocate(t)
	_, lerr := os.Lstat(filepath.Join(outer, ".git"))
	t.Logf("outer .git exists=%v; locateRepoRoot got=%q err=%v notInRepo=%v", lerr == nil, got, err, err != nil && errorsIsNotInRepo(err))
}

