// Re-sealed chunk with a stem different from cn, fresh damage under the
// marker, crash after the chunk was removed and before the record was added.
func TestSFHProbeOtherStemCrashAfterRemove(t *testing.T) {
	repo, sealedDir, live, _, cn := quarantineSetup(t, false)
	writeLive(t, live, 200)
	if _, err := Quarantine(repo, sealedDir, cn, live, "ts mismatch", redact.Prose, keepLine, noRule); err != nil {
		t.Fatal(err)
	}
	re := SessionChunkFile(200, 200)
	rePath := filepath.Join(sealedDir, re)
	if _, err := os.Stat(rePath); err != nil {
		t.Fatalf("no reseal chunk: %v", err)
	}
	fmt.Println("after first run, index:\n" + gitOut(t, repo, "ls-files", "-s", "--", "sealed"))
	body := leaky200()
	if err := os.WriteFile(rePath, body, 0o600); err != nil {
		t.Fatal(err)
	}
	rc, _ := Classify(re, SessionNS)
	hashed, err := corruptHashName(sealedDir, rc.Stem(), body)
	if err != nil {
		t.Fatal(err)
	}
	// crash after os.Remove(src), before GitAdd(dst)
	if err := saveOriginal(repo, rc.Stem(), body); err != nil {
		t.Fatal(err)
	}
	if err := writeRecord(filepath.Join(sealedDir, hashed), body, "names another user's home"); err != nil {
		t.Fatal(err)
	}
	gitOut(t, repo, "rm", "--cached", "-q", "--", filepath.Join("sealed", re))
	if err := os.Remove(rePath); err != nil {
