	fmt.Println("index after re-run:\n" + gitOut(t, repo, "ls-files", "-s", "--", "sealed"))
}

// Same, but the failure is a failed add (index.lock) in the real code path.
func TestSFHProbeOtherStemFailedAdd(t *testing.T) {
	repo, sealedDir, live, _, cn := quarantineSetup(t, false)
	writeLive(t, live, 200)
	if _, err := Quarantine(repo, sealedDir, cn, live, "ts mismatch", redact.Prose, keepLine, noRule); err != nil {
		t.Fatal(err)
	}
	re := SessionChunkFile(200, 200)
	rePath := filepath.Join(sealedDir, re)
	if err := os.WriteFile(rePath, leaky200(), 0o600); err != nil {
		t.Fatal(err)
	}
	lock := filepath.Join(repo, ".git", "index.lock")
	if err := os.WriteFile(lock, nil, 0o600); err != nil {
		t.Fatal(err)
	}
	var err error
	first := captureNotices(t, func() {
		_, err = Quarantine(repo, sealedDir, cn, live, "ts mismatch", redact.Prose, keepLine, homeCheck)
	})
	fmt.Printf("locked run err=%v notices=%q\n", err, first)
