package audit

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/punt-labs/ethos/v4/internal/redact"
)

func indexLeaks(t *testing.T, repo string) bool {
	cmd := exec.Command("git", "grep", "--cached", "-l", "~[redacted-user]")
	cmd.Dir = repo
	out, _ := cmd.Output()
	return len(strings.TrimSpace(string(out))) > 0
}

func runQ(t *testing.T, repo, sealedDir, live string, cn ChunkName) (string, error) {
	var err error
	out := captureNotices(t, func() {
		_, err = Quarantine(repo, sealedDir, cn, live, "ts mismatch", redact.Prose, keepLine, homeCheck)
	})
	return out, err
}

func TestSFHProbeMatrix(t *testing.T) {
	body := leakyChunkBody()
	type step func(t *testing.T, repo, sealedDir, live, name string, cn ChunkName)
	cases := map[string]struct {
		state  string
		marker bool
		prep   step
	}{
		"fresh-untracked":    {state: "untracked"},
		"fresh-committed":    {state: "committed"},
		"fresh-staged-mod":   {state: "staged-then-modified"},
		"hashed": {state: "committed", prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			os.WriteFile(filepath.Join(sd, name+".corrupt"), []byte("earlier evidence\n"), 0o600)
		}},
		"older-git-mv": {state: "committed", prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			gitOut(t, repo, "mv", "--", filepath.Join("sealed", name), filepath.Join("sealed", name+".corrupt"))
		}},
		"older-git-mv+marker": {state: "committed", marker: true, prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			gitOut(t, repo, "mv", "--", filepath.Join("sealed", name), filepath.Join("sealed", name+".corrupt"))
		}},
		"crash-after-save": {state: "committed", prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			saveOriginal(repo, cn.Stem(), body)
		}},
		"crash-after-record": {state: "committed", prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			saveOriginal(repo, cn.Stem(), body)
			writeRecord(filepath.Join(sd, name+".corrupt"), body, "names another user's home")
		}},
		"crash-after-rmcached": {state: "committed", prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			saveOriginal(repo, cn.Stem(), body)
			writeRecord(filepath.Join(sd, name+".corrupt"), body, "names another user's home")
			gitOut(t, repo, "rm", "--cached", "-q", "--", filepath.Join("sealed", name))
		}},
		"crash-after-remove": {state: "committed", prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			saveOriginal(repo, cn.Stem(), body)
			writeRecord(filepath.Join(sd, name+".corrupt"), body, "names another user's home")
			gitOut(t, repo, "rm", "--cached", "-q", "--", filepath.Join("sealed", name))
			os.Remove(filepath.Join(sd, name))
		}},
		"crash-after-record+marker": {state: "committed", marker: true, prep: func(t *testing.T, repo, sd, live, name string, cn ChunkName) {
			saveOriginal(repo, cn.Stem(), body)
			writeRecord(filepath.Join(sd, name+".corrupt"), body, "names another user's home")
		}},
	}
	for nm, c := range cases {
		t.Run(nm, func(t *testing.T) {
			repo, sd, live, name, cn := quarantineSetupState(t, c.state)
			if c.marker {
				if err := writeMarkerAtomic(sd, cn.MarkerFile(), Marker{Chunk: cn.Stem(), VerifiedLast: 300, Reason: "x"}); err != nil {
					t.Fatal(err)
				}
			}
			if c.prep != nil {
				c.prep(t, repo, sd, live, name, cn)
			}
			o1, e1 := runQ(t, repo, sd, live, cn)
			o2, e2 := runQ(t, repo, sd, live, cn)
			fmt.Printf("%-28s run1 err=%v n=%d | run2 err=%v n=%d | indexLeaks=%v\n", nm, e1, strings.Count(o1, "was withheld"), e2, strings.Count(o2, "was withheld"), indexLeaks(t, repo))
		})
	}
}

