func sfhLine(i int) []byte {
	ti := map[string]any{"command": fmt.Sprintf("echo %d", i)}
	env := map[string]any{"tool_input": ti}
	b, _ := json.Marshal(map[string]any{
		"ts": fmt.Sprintf("2026-05-22T10:%02d:%02dZ", i/60, i%60), "session": "sess-p", "tool": "Bash",
		"tool_input": ti, "tool_input_hash": hashToolInput(env),
	})
	return append(b, '\n')
}

func sfhCount(path string) map[string]int {
	m := map[string]int{}
	data, err := os.ReadFile(path)
	if err != nil {
		return m
	}
	for _, l := range bytes.Split(data, []byte("\n")) {
		var e auditEntry
		if json.Unmarshal(l, &e) == nil {
			if c, ok := e.ToolInput["command"].(string); ok {
				m[c]++
			}
		}
	}
	return m
}

func sfhSetup(t *testing.T) (globalDir, repoRoot, sessionDir, legacy string) {
	t.Setenv("HOME", t.TempDir())
	globalDir = filepath.Join(t.TempDir(), "global")
	repoRoot = t.TempDir()
	sessionDir = repoSessionDir(t, repoRoot, "2026-05-22", "sess-p")
	os.MkdirAll(globalDir, 0o700)
	legacy = filepath.Join(globalDir, "sess-p.audit.jsonl")
	return
}

func sfhRun(t *testing.T, g, r string, dry bool) (string, string, error) {
	var out bytes.Buffer
	var err error
	n := testhelpers.CaptureStderr(t, func() { err = MigrateAudit(g, r, dry, &out) })
	return n, out.String(), err
}

// An appender holding the legacy fd open across the whole migration.
