func TestLeakRuleText_NeverMatchesALeakPattern(t *testing.T) {
	const home = "~[redacted-user]"
	for name, sample := range map[string]string{
		"own home":  "cat ~[redacted-user]/x",
		"own slug":  "-~-[redacted-slug]",
