		}
		return false, fmt.Errorf("git rev-parse --show-toplevel: %s", strings.TrimSpace(string(ee.Stderr)))
	}
	top, err := os.Stat(strings.TrimSpace(string(out)))
	if err != nil {
		return false, nil
	}
	d, err := os.Stat(dir)
	return err == nil && os.SameFile(top, d), nil
}

