func TestSFHRestageNoticeLost(t *testing.T) {
	repo, sealedDir, live, name, cn := quarantineSetup(t, false)
	corrupt := filepath.Join(sealedDir, name+".corrupt")
	if err := os.Rename(filepath.Join(sealedDir, name), corrupt); err != nil {
		t.Fatal(err)
	}
	gitOut(t, repo, "add", "--", "sealed") // index holds the leaky bytes
	clean := []byte("{\"ts\":\"" + FormatLineTS(100) + "\",\"cwd\":\"/x\"}\n")
	if err := os.WriteFile(corrupt, clean, 0o600); err != nil {
		t.Fatal(err)
	}
	// make the live read fail
	if err := os.Remove(live); err != nil && !os.IsNotExist(err) {
		t.Fatal(err)
	}
	if err := os.Mkdir(live, 0o700); err != nil {
		t.Fatal(err)
	}
	var err error
	first := captureNotices(t, func() {
		_, err = Quarantine(repo, sealedDir, cn, live, "ts mismatch", redact.Prose, keepLine, homeCheck)
	})
	idx := gitOut(t, repo, "show", ":"+filepath.Join("sealed", name+".corrupt"))
	t.Logf("first err=%v notices=%q index-leaks=%v", err, first, strings.Contains(idx, "~[redacted-user]"))
	os.Remove(live)
	writeLive(t, live, 100, 200, 300)
	second := captureNotices(t, func() {
		_, err = Quarantine(repo, sealedDir, cn, live, "ts mismatch", redact.Prose, keepLine, homeCheck)
	})
	q, _ := os.ReadDir(QuarantineDir(repo))
	t.Logf("second err=%v notices=%q quarantine-files=%d", err, second, len(q))
}
