// TestSFH28Reread feeds values base stored through this build's Path and
// leak check: a value base wrote must not be refused or rewritten on a
// later write of the same record.
func TestSFH28Reread(t *testing.T) {
	f, err := os.Open(os.Getenv("SFH28_IN"))
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	refused, changed, total := 0, 0, 0
	for sc.Scan() {
		parts := strings.SplitN(sc.Text(), "\t", 2)
		home := parts[0]
		v, err := strconv.Unquote(parts[1])
		if err != nil {
			t.Fatal(err)
		}
		r := PathRedactor{Home: home, Repo: home + "/repo"}
		p := r.Path(v)
		total++
		if lr := r.LeakRuleFor(p, true); lr != "" {
			refused++
			if refused <= 10 {
				fmt.Printf("REFUSED home=%s stored=%q path=%q rule=%q\n", home, v, p, lr)
			}
		} else if p != v {
			changed++
			if changed <= 10 {
				fmt.Printf("CHANGED home=%s stored=%q path=%q\n", home, v, p)
			}
		}
	}
	fmt.Printf("total=%d refused=%d changed=%d\n", total, refused, changed)
}

