import json, sys, re, collections

PAT = {
    "own_abs": re.compile(r"~[redacted-user]", re.I),
    "own_rel": re.compile(r"(?<![A-Za-z0-9_/])home/zed(?![A-Za-z0-9_])", re.I),
    "own_slug": re.compile(r"-~-[redacted-slug]", re.I),
    "foreign": re.compile(r"(home|users)(/|\\\\|%2f|-)(bob|al)(?![A-Za-z0-9_])", re.I),
}


def tags(s):
    return {k for k, p in PAT.items() if p.search(s)}


def hook(hf, bf):
    cnt = collections.Counter()
    ex = collections.defaultdict(list)
    for lh, lb in zip(open(hf), open(bf)):
        h, b = json.loads(lh), json.loads(lb)
        assert h["In"] == b["In"] and h["Key"] == b["Key"]
        for fld in ("Line", "CraftLine"):
            new = tags(h[fld]) - tags(b[fld])
            if new:
                k = "%s key=%s new=%s" % (fld, h["Key"], sorted(new))
                cnt[k] += 1
                if len(ex[k]) < 6:
                    ex[k].append((h["In"], h["Stored"] if fld == "Line" else h["CraftLine"][:160], b["Stored"] if fld == "Line" else b["CraftLine"][:160]))
        if h["Stored"] != b["Stored"]:
            k = "stored_differs key=%s headtags=%s" % (h["Key"], sorted(tags(h["Stored"])))
            cnt[k] += 1
            if len(ex[k]) < 6:
                ex[k].append((h["In"], h["Stored"], b["Stored"]))
    for k in sorted(cnt):
        print(k, cnt[k])
    for k in sorted(ex):
        print("==", k)
        for e in ex[k]:
            print("  ", repr(e))


def mission(hf, bf):
    cnt = collections.Counter()
    ex = collections.defaultdict(list)
    for lh, lb in zip(open(hf), open(bf)):
        h, b = json.loads(lh), json.loads(lb)
        hs = not h["LeakFor"]
        bs = not b["LeakFor"]
        if hs:
            new = tags(h["Path"]) - (tags(b["Path"]) if bs else set())
            if new:
                k = "stored_new_leak base=%s new=%s" % ("stored" if bs else "refused", sorted(new))
                cnt[k] += 1
                if len(ex[k]) < 8:
                    ex[k].append((h["In"], h["Path"], b["Path"], b["LeakFor"]))
        if hs and not h["Idem"]:
            cnt["head_not_idempotent"] += 1
            if len(ex["head_not_idempotent"]) < 8:
                ex["head_not_idempotent"].append((h["In"], h["Path"]))
        if hs and not bs:
            cnt["head_stores_base_refused"] += 1
            if len(ex["head_stores_base_refused"]) < 8:
                ex["head_stores_base_refused"].append((h["In"], h["Path"], b["Path"], b["LeakFor"]))
        if not hs and bs:
            cnt["head_refuses_base_stored"] += 1
            if len(ex["head_refuses_base_stored"]) < 8:
                ex["head_refuses_base_stored"].append((h["In"], h["Path"], h["LeakFor"], b["Path"]))
        if hs and bs and h["Exp"] != h["In"] and b["Exp"] == b["In"] and not h["ExpErr"]:
            cnt["roundtrip_lost"] += 1
    for k in sorted(cnt):
        print(k, cnt[k])
    for k in sorted(ex):
        print("==", k)
        for e in ex[k]:
            print("  ", repr(e))


