package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/punt-labs/ethos/v4/internal/mission"
)

// strict mirrors decodeEventLine.
func strict(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	var e mission.Event
	if err := dec.Decode(&e); err != nil {
		return err
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		return fmt.Errorf("trailing")
	}
	if _, err := time.Parse(time.RFC3339, e.TS); err != nil {
		return err
	}
	if strings.TrimSpace(e.Event) == "" || strings.TrimSpace(e.Actor) == "" {
		return fmt.Errorf("missing event/actor")
	}
	return nil
}

func main() {
	root := filepath.Join(os.Args[1], ".punt-labs", "ethos", "missions")
	files, lines, bad := 0, 0, 0
	_ = filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(p, ".jsonl") {
			return nil
		}
		files++
		f, _ := os.Open(p)
		defer f.Close()
		sc := bufio.NewScanner(f)
		sc.Buffer(make([]byte, 1<<20), 1<<24)
		n := 0
		for sc.Scan() {
			n++
			if len(bytes.TrimSpace(sc.Bytes())) == 0 {
				continue
			}
			lines++
			if err := strict(sc.Bytes()); err != nil {
				bad++
				rel, _ := filepath.Rel(root, p)
				fmt.Printf("BAD %s:%d %v\n", rel, n, err)
			}
		}
		return nil
	})
	fmt.Printf("files=%d lines=%d bad=%d\n", files, lines, bad)
}

