// TestSFHProbeRecords re-redacts every stored record of the copy at SFH_REPO
// (and the legacy missions under SFH_GLOBAL) as a rewrite would, and prints
// each refusal. It also LoadEvents every repo mission.
func TestSFHProbeRecords(t *testing.T) {
	repo := os.Getenv("SFH_REPO")
	global := os.Getenv("SFH_GLOBAL")
	if repo == "" {
		t.Skip()
	}
	s := NewStoreWithRoots(repo, global)
	ents, _ := os.ReadDir(filepath.Join(repo, ".punt-labs/ethos/missions"))
	var ids []string
	for _, e := range ents {
		if e.IsDir() && strings.HasPrefix(e.Name(), "m-") {
			ids = append(ids, e.Name())
		}
	}
	gents, _ := os.ReadDir(filepath.Join(global, "missions"))
	for _, e := range gents {
		n := e.Name()
		if strings.HasSuffix(n, ".yaml") && !strings.Contains(n, ".results.") && !strings.Contains(n, ".reflections.") {
			ids = append(ids, strings.TrimSuffix(n, ".yaml"))
		}
	}
	sort.Strings(ids)
	nEv, nWarn := 0, 0
	for _, id := range ids {
		c, err := s.Load(id)
		if err != nil {
			fmt.Printf("LOAD %s: %v\n", id, err)
			continue
		}
		if _, err := RedactRecord(repo, *c); err != nil {
			fmt.Printf("REFUSE contract %s: %v\n", id, err)
		}
		if rs, err := s.LoadResults(id); err != nil {
			fmt.Printf("LOADRES %s: %v\n", id, err)
		} else if _, err := RedactRecord(repo, resultsFile{Results: rs}); err != nil {
			fmt.Printf("REFUSE results %s: %v\n", id, err)
		}
		if rs, err := s.LoadReflections(id); err != nil {
			fmt.Printf("LOADREF %s: %v\n", id, err)
		} else if _, err := RedactRecord(repo, reflectionsFile{Reflections: rs}); err != nil {
			fmt.Printf("REFUSE reflections %s: %v\n", id, err)
		}
		dels, _ := filepath.Glob(filepath.Join(repo, ".punt-labs/ethos/missions", id, "delegations", "*", "record.yaml"))
		for _, p := range dels {
			d, err := LoadDelegation(p)
			if err != nil {
				fmt.Printf("LOADDEL %s: %v\n", p, err)
				continue
			}
			if _, err := RedactRecord(repo, *d); err != nil {
				fmt.Printf("REFUSE delegation %s: %v\n", p, err)
			}
		}
		ev, warn, err := s.LoadEvents(id)
		if err != nil {
			fmt.Printf("EVENTS %s: %v\n", id, err)
		}
		nEv += len(ev)
		nWarn += len(warn)
		for _, w := range warn {
			fmt.Printf("EVWARN %s: %s\n", id, w)
		}
	}
	fmt.Printf("missions=%d events=%d warnings=%d\n", len(ids), nEv, nWarn)
}

