import json, sys, re

PAT = {
    "own_abs": re.compile(r"~[redacted-user]", re.I),
    "own_rel": re.compile(r"(?<![A-Za-z0-9_/])home/zed(?![A-Za-z0-9_])", re.I),
    "own_slug": re.compile(r"-~-[redacted-slug]", re.I),
    "foreign": re.compile(r"(home|users)(/|\\\\|%2f|-)(bob|al)(?![A-Za-z0-9_])", re.I),
}


def tags(s):
    return sorted(k for k, p in PAT.items() if p.search(s))


def redacted(stored):
    return "redacted" in stored or stored in ("", "null")


def load(p):
    return [json.loads(l) for l in open(p)]


def hook(d):
    B, M, H = (load(d + "/hook_%s.jsonl" % t) for t in ("base", "mid", "head"))
    seen = set()
    print("## HOOK (key=file_path representative; Line = written entry)")
    for b, m, h in zip(B, M, H):
        assert b["In"] == h["In"] == m["In"] and b["Key"] == h["Key"]
        if h["Stored"] == b["Stored"]:
            continue
        key = (h["In"], h["Key"] in ("file_path",), h["Stored"], b["Stored"])
        k2 = (h["In"], h["Key"])
        tag = "h_stores_b_redacted" if (redacted(b["Stored"]) and not redacted(h["Stored"])) else ("h_redacts_b_stored" if (redacted(h["Stored"]) and not redacted(b["Stored"])) else "other")
        sig = (h["In"], h["Stored"], b["Stored"], tag)
        if sig in seen:
            continue
        seen.add(sig)
        mid_same = "mid=head" if m["Stored"] == h["Stored"] else "mid=%s" % m["Stored"]
        print("%s\tkey=%s\tin=%r\thead=%s\tbase=%s\t%s\tleaktags=%s" % (tag, h["Key"], h["In"], h["Stored"], b["Stored"], mid_same, tags(h["Stored"])))


def slug(d):
    rows = {}
    for t in ("base", "mid", "head"):
        rows[t] = [l.rstrip("\n").split("\t") for l in open(d + "/slug_%s.txt" % t)]
    print("## STORE write_set probe")
    for b, m, h in zip(rows["base"], rows["mid"], rows["head"]):
        if not (b[4] == m[4] == h[4]):
            print("in=%s\tbase=%s\tmid=%s\thead=%s" % (h[0], b[4], m[4], h[4]))


def mission(d):
    B, M, H = (load(d + "/m_%s.jsonl" % t) for t in ("base", "mid", "head"))
    print("## MISSION fuzz (Path then LeakRuleFor(path,true))")
    n = 0
    for b, m, h in zip(B, M, H):
        hs, bs, ms = not h["LeakFor"], not b["LeakFor"], not m["LeakFor"]
        if hs != bs or hs != ms or h["Path"] != b["Path"]:
            n += 1
            if n <= 60:
                print("in=%r head_path=%r head=%s mid=%s base=%s leaktags=%s" % (h["In"], h["Path"], "stored" if hs else "refused:" + h["LeakFor"], "stored" if ms else "refused", "stored" if bs else "refused", tags(h["Path"])))
    print("total differing", n)


def store(d):
    B, M, H = (load(d + "/store_%s.jsonl" % t) for t in ("base", "mid", "head"))
    print("## STORE fixed")
    for b, m, h in zip(B, M, H):
        if (b["Err"] == "") != (h["Err"] == "") or b["Stored"] != h["Stored"] or (m["Err"] == "") != (h["Err"] == ""):
            print("field=%s in=%r head=%r base=%r mid=%r" % (h["Field"], h["In"], h["Stored"] or ("ERR " + h["Err"][:90]), b["Stored"] or ("ERR " + b["Err"][:90]), m["Stored"] or ("ERR " + m["Err"][:60])))


