func TestZZ33Store(t *testing.T) {
	inF, err := os.Open(os.Getenv("ZZ33_IN"))
	if err != nil {
		t.Fatal(err)
	}
	var ins []string
	sc := bufio.NewScanner(inF)
	for sc.Scan() {
		ins = append(ins, sc.Text())
	}
	inF.Close()
	f, err := os.Create(os.Getenv("ZZ33_OUT"))
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	enc := json.NewEncoder(f)
	for _, home := range []string{"/root", "~[redacted-user]"} {
		t.Setenv("HOME", home)
		for i, in := range ins {
			for _, field := range []string{"write_set", "files", "files_changed"} {
				repo := t.TempDir()
				s := NewStoreWithRoots(repo, t.TempDir())
				c := newContract(fmt.Sprintf("m-2026-08-06-%03d", 100+i%800))
				row := zz33SRow{Home: home, Field: field, In: in}
				switch field {
				case "write_set":
					c.WriteSet = []string{in}
				case "files":
					c.Inputs.Files = []string{in}
				}
				if err := s.Create(c); err != nil {
					row.Err = err.Error()
				} else if field == "files_changed" {
					got, _ := s.Load(c.MissionID)
					r := resultFor(got, VerdictPass)
					r.FilesChanged = []FileChange{{Path: in, Added: 1}}
					if err := s.AppendResult(c.MissionID, r); err != nil {
						row.Err = err.Error()
					} else {
						rs, lerr := s.LoadResults(c.MissionID)
						if lerr != nil {
							row.Err = "LOAD " + lerr.Error()
						} else {
							row.Stored = fmt.Sprintf("%q", rs[len(rs)-1].FilesChanged[0].Path)
						}
					}
				} else {
					got, lerr := s.Load(c.MissionID)
					if lerr != nil {
						row.Err = "LOAD " + lerr.Error()
					} else if field == "write_set" {
						row.Stored = fmt.Sprintf("%q", got.WriteSet)
					} else {
						row.Stored = fmt.Sprintf("%q", got.Inputs.Files)
					}
				}
