// The skip path runs scrubFile with no lock. A concurrent Create that lands
// between missionDirAbsent and the read leaves a freshly written record for
// the unlocked scrub to read; a write back is a lost-update risk only if the
// scrub would rewrite a freshly written record.
func TestProbe_ScrubOfFreshRecordsWritesNothing(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	repo, global := t.TempDir(), t.TempDir()
	s := NewStoreWithRoots(repo, global)
	const mid, did = "m-2026-07-21-040", "d-2026-07-21-040"
	c := &Contract{
		MissionID: mid, Status: StatusOpen,
		CreatedAt: "2026-05-22T21:30:00Z", UpdatedAt: "2026-05-22T21:30:00Z",
		Leader: "claude", Worker: "bwk",
		Evaluator:       Evaluator{Handle: "djb", PinnedAt: "2026-05-22T21:30:00Z"},
		WriteSet:        []string{"internal/"},
		Tools:           []string{"Read", "Write"},
		SuccessCriteria: []string{"make check passes in " + filepath.Join(home, "x")},
		Budget:          Budget{Rounds: 3, ReflectionAfterEach: true},
		CurrentRound:    1,
		Preconditions: []Precondition{{Form: PreconditionFormExplicit,
			RequireRead: []string{filepath.Join(repo, "cfg", "a.yaml"), filepath.Join(home, "b")},
			Message:     "read it first"}},
	}
	if err := s.Create(c); err != nil {
		t.Fatal(err)
	}
	if _, err := WriteDelegationSkeleton(repo, mid, did, DelegationSkeleton{
		Tier: TierB, AgentType: "bwk", BoundVia: BoundViaSidecarDispatch, Session: filepath.Join(home, "sess"),
	}); err != nil {
		t.Fatal(err)
	}
	rels := []string{
		".punt-labs/ethos/missions/" + mid + "/contract.yaml",
		".punt-labs/ethos/missions/" + mid + "/delegations/" + did + "/record.yaml",
		".punt-labs/ethos/missions.jsonl",
	}
	res, err := ScrubFiles(repo, global, rels, false)
	t.Logf("fresh: res=%+v err=%v", res, err)

	// Race: scrub loop (unlocked skip path is taken only when the dir is
	// absent at stat time) against a stream of Updates.
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < 200; i++ {
			if _, err := ScrubFiles(repo, global, rels[:1], false); err != nil {
				t.Errorf("scrub: %v", err)
				return
			}
		}
	}()
	for i := 0; i < 50; i++ {
		if err := s.Update(mid, func(c *Contract) error { c.CurrentRound = 1 + i%3; return nil }); err != nil {
			t.Logf("update err: %v", err)
			break
		}
	}
	wg.Wait()
}

