package hook

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/punt-labs/ethos/v4/internal/mission"
	"github.com/punt-labs/ethos/v4/internal/redact"
)

// P1: real digests through both guards and the credential pass.
func TestProbe_RealDigestsSurviveGuards(t *testing.T) {
	changedGuard, changedMission, changedSecrets :[redacted-secret] 0, 0, 0
	repo := t.TempDir()
	for i := 0; i < 5000; i++ {
		k := make([]byte, 32)
		_, _ = rand.Read(k)
		d := pathDigest(k, "/r", fmt.Sprintf("src/nav--home-%d.scss", i))
		line := []byte(`{"ts":"2026-01-01T00:00:00Z","session":"s","tool":"Read","tool_input":{"file_path":"[redacted-path]"},"path_format":2,"path_digests":{"file_path":"` + d + `","files[2]":"` + d + `"}}`)
		out, _, _ := guardAuditLineFull(line)
		if !strings.Contains(string(out), `"file_path":"`+d) || !strings.Contains(string(out), `"files[2]":"`+d) {
			changedGuard++
			if changedGuard < 3 {
				t.Logf("guard changed: %s", out)
			}
		}
		out, _, _ = missionLineGuard(repo)(line)
		if !strings.Contains(string(out), d) {
			changedMission++
		}
		if redact.SecretsString(d) != d {
			changedSecrets++
		}
	}
	t.Logf("guard changed %d, mission guard changed %d, secrets changed %d of 5000", changedGuard, changedMission, changedSecrets)
}

// P2: no repo root -> key created relative to cwd?
func TestProbe_EmptyRepoRootWritesKeyInCwd(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	cwd := t.TempDir()
	old, _ := os.Getwd()
	defer os.Chdir(old)
	_ = os.Chdir(cwd)
	input := map[string]any{"tool_name": "Read", "tool_input": map[string]any{
		"file_path": filepath.Join(cwd, "src", "nav--home-page.scss")}}
	e := buildAuditEntry(input, "sess-x", "", time.Now())
	t.Logf("stored file_path=%v digests=%v", e.ToolInput["file_path"], e.PathDigests)
	_, err := os.Stat(filepath.Join(cwd, ".punt-labs", "local", "ethos", "path-digest.key"))
	t.Logf("key in cwd: err=%v", err)
	ents, _ := os.ReadDir(cwd)
	for _, x := range ents {
		t.Logf("cwd entry: %s", x.Name())
	}
}

// P3: concurrent creation.
func TestProbe_ConcurrentKey(t *testing.T) {
	repo := t.TempDir()
	var wg sync.WaitGroup
	keys := make([]string, 64)
	errs := make([]error, 64)
	for i := range keys {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			k, err := digestKey(repo)
			keys[i], errs[i] = hex.EncodeToString(k), err
		}(i)
	}
	wg.Wait()
	distinct := map[string]bool{}
	for i := range keys {
		if errs[i] != nil {
			t.Logf("err %d: %v", i, errs[i])
		}
		distinct[keys[i]] = true
	}
	t.Logf("distinct keys: %d", len(distinct))
	ents, _ := os.ReadDir(filepath.Join(repo, ".punt-labs", "local", "ethos"))
	for _, x := range ents {
		t.Logf("zone entry: %s", x.Name())
	}
}

// P4: spellings and cross-file matches.
func TestProbe_Spellings(t *testing.T) {
	repo, global := digestRepo(t)
	outside := filepath.Join(filepath.Dir(repo), "elsewhere", "nav--home-page.scss")
	inside := filepath.Join(repo, "src", "nav--home-page.scss")
	auditRead(t, repo, global, "s-in", inside)
	auditRead(t, repo, global, "s-out", outside)
	c := makeContractWithPreconditions([]mission.Precondition{{
		Form: mission.PreconditionFormImplicit, Message: "read before write",
	}}, mission.Inputs{}, nil)
	try := func(sess, p string) {
		_, deny, err := EvaluatePreconditions(c, "Write", map[string]any{"file_path": p}, sess, repo, repo)
		t.Logf("sess=%s write=%q deny=%v err=%v", sess, p, deny, err)
	}
	try("s-in", inside)
	try("s-in", "src/nav--home-page.scss")
	try("s-in", "./src/../src/nav--home-page.scss")
	try("s-in", "nav--home-page.scss")
	try("s-in", "SRC/nav--home-page.scss")
	try("s-in", filepath.Join(repo, "x", "..", "src", "nav--home-page.scss"))
	try("s-out", outside)
	try("s-out", "../elsewhere/nav--home-page.scss")
	try("s-out", inside)
	try("s-in", outside)
	// symlinked root spelling
	link := filepath.Join(filepath.Dir(repo), "repolink")
	_ = os.Symlink(repo, link)
	try("s-in", filepath.Join(link, "src", "nav--home-page.scss"))
	_, deny, err := EvaluatePreconditions(c, "Write", map[string]any{"file_path": filepath.Join(link, "src", "nav--home-page.scss")}, "s-in", link, link)
	t.Logf("root=link, write=link/src/nav: deny=%v err=%v", deny, err)
	// relative repo root
	old, _ := os.Getwd()
	defer os.Chdir(old)
	_ = os.Chdir(filepath.Dir(repo))
	_, deny, err = EvaluatePreconditions(c, "Write", map[string]any{"file_path": inside}, "s-in", "repo", "repo")
	t.Logf("root=relative 'repo', write=abs inside: deny=%v err=%v", deny, err)
}

// P5: a second checkout (worktree root) with its own key; same relative path.
func TestProbe_TwoCheckouts(t *testing.T) {
	repo, global := digestRepo(t)
	other := filepath.Join(filepath.Dir(repo), "other")
	_ = os.MkdirAll(other, 0o700)
	initGitRepo(t, other)
	auditRead(t, repo, global, "s2", filepath.Join(repo, "src", "nav--home-page.scss"))
	c := makeContractWithPreconditions([]mission.Precondition{{
		Form: mission.PreconditionFormImplicit, Message: "read before write",
	}}, mission.Inputs{}, nil)
	// copy the live audit to other (as if sealed + merged), but other has its own key
	src := liveAuditPath(repo, "s2")
	b, _ := os.ReadFile(src)
	_ = os.MkdirAll(filepath.Dir(liveAuditPath(other, "s2")), 0o700)
	_ = os.WriteFile(liveAuditPath(other, "s2"), b, 0o600)
	_, _ = digestKey(other)
	_, deny, err := EvaluatePreconditions(c, "Write", map[string]any{"file_path": filepath.Join(other, "src", "nav--home-page.scss")}, "s2", other, other)
	t.Logf("other checkout, distinct key: deny=%v err=%v", deny, err)
	// shared key (copied)
	kb, _ := os.ReadFile(digestKeyPath(repo))
	_ = os.Remove(digestKeyPath(other))
	_ = os.WriteFile(digestKeyPath(other), kb, 0o600)
	_, deny, err = EvaluatePreconditions(c, "Write", map[string]any{"file_path": filepath.Join(other, "src", "nav--home-page.scss")}, "s2", other, other)
	t.Logf("other checkout, same key: deny=%v err=%v", deny, err)
}

