// P6: key unreadable at evaluation time: what does the deny say?
func TestProbe_KeyUnreadableAtEval(t *testing.T) {
	repo, global := digestRepo(t)
	p := filepath.Join(repo, "src", "nav--home-page.scss")
	auditRead(t, repo, global, "s6", p)
	c := makeContractWithPreconditions([]mission.Precondition{{
		Form: mission.PreconditionFormImplicit, Message: "read before write",
	}}, mission.Inputs{}, nil)
	_ = os.WriteFile(digestKeyPath(repo), []byte("short"), 0o600)
	var reason string
	var deny bool
	var err error
	stderr := captureStderr(t, func() {
		reason, deny, err = EvaluatePreconditions(c, "Write", map[string]any{"file_path": p}, "s6", repo, repo)
	})
	t.Logf("deny=%v reason=%q err=%v stderr=%q", deny, reason, err, stderr)
	// Re-read: does a new Read help?
	stderr = captureStderr(t, func() { auditRead(t, repo, global, "s6", p) })
	t.Logf("re-read stderr=%q", stderr)
	reason, deny, err = EvaluatePreconditions(c, "Write", map[string]any{"file_path": p}, "s6", repo, repo)
	t.Logf("after re-read: deny=%v reason=%q err=%v", deny, reason, err)
}

