package mission

import (
	"strings"
	"testing"

	"github.com/punt-labs/ethos/v4/internal/redact"
)

func cr42OldGlued(s string) bool {
	low := strings.ToLower(s)
	flag := low != "" && (low[0] == '-' || low[0] == '+')
	for _, h := range []string{"/home/", "/users/"} {
		for i := 0; ; {
			j := strings.Index(low[i:], h)
			if j < 0 {
				break
			}
			at := i + j
			if flag || (at > 0 && (low[at-1] == '-' || low[at-1] == '+')) {
				return true
			}
			i = at + 1
		}
	}
	return false
}

func TestCR42Glued(t *testing.T) {
	pre := []string{"", "x", "x/", "@", "*", "x@", "x*", "**", "@scope", "a.b@", "x/@", "x/*", "_", ".", "x.", "+", "-", "x=", "x:"}
	mid := []string{"~[redacted-user]", "~[redacted-user]", "~[redacted-user]", "~[redacted-user]", "~[redacted-user]"}
	suf := []string{"", "/", "/f", "/*", "-x", "@x"}
	for _, p := range pre {
		for _, m := range mid {
			for _, s := range suf {
				v := p + m + s
				for _, w := range []string{v, "<repo>/" + v} {
					rel := strings.TrimPrefix(w, "<repo>/")
					if !redact.RepoRelative(rel) {
