package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"

	"github.com/punt-labs/ethos/v4/internal/redact"
)

// For each file: report raw-level and decoded-level credential/email hits,
// with the first differing span of SecretsString (truncated to 60 bytes) so
// the triggering rule can be identified.
func diffSpan(a, b string) string {
	i := 0
	for i < len(a) && i < len(b) && a[i] == b[i] {
		i++
	}
	s := i - 30
	if s < 0 {
		s = 0
	}
	e := i + 40
	if e > len(a) {
		e = len(a)
	}
	return a[s:e]
}

func walk(v any, path string) {
	switch x := v.(type) {
	case string:
		if r := redact.SecretsString(x); r != x {
			fmt.Printf("  decoded cred at %s: %q\n", path, diffSpan(x, r))
		}
		if m := redact.EmailPattern.FindString(x); m != "" {
			fmt.Printf("  decoded email at %s: %q\n", path, m)
		}
	case []any:
		for i, e := range x {
			walk(e, fmt.Sprintf("%s[%d]", path, i))
		}
	case map[string]any:
		for k, e := range x {
			if r := redact.SecretsString(k); r != k {
				fmt.Printf("  key cred at %s: %q\n", path, k)
			}
			walk(e, path+"."+k)
		}
	}
}

func main() {
	for _, f := range os.Args[1:] {
		b, err := os.ReadFile(f)
		if err != nil {
			fmt.Println("ERR", err)
			continue
		}
		fmt.Println("FILE", f)
		s := string(b)
		if r := redact.SecretsString(s); r != s {
			fmt.Printf(" raw cred: %q\n", diffSpan(s, r))
		}
		for i, l := range bytes.Split(b, []byte("\n")) {
			var v any
			d := json.NewDecoder(bytes.NewReader(l))
			d.UseNumber()
			if d.Decode(&v) != nil {
				continue
			}
			fmt.Printf(" line %d\n", i+1)
			walk(v, "")
		}
	}
}

