func TestZZ_LoadRealMissions(t *testing.T) {
	data := os.Getenv("ZZ_DATA")
	global := os.Getenv("ZZ_GLOBAL")
	out := os.Getenv("ZZ_OUT")
	if data == "" {
		t.Skip()
	}
	s := NewStoreWithRoots(data, global)
	ids, err := s.List()
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(ids)
	var lines []string
	fails := 0
	for _, id := range ids {
		c, err := s.Load(id)
		if err != nil {
			fails++
			lines = append(lines, fmt.Sprintf("%s LOADERR %v", id, err))
			continue
		}
		rs, rerr := s.LoadResults(id)
		fs, ferr := s.LoadReflections(id)
		b, _ := json.Marshal(struct {
			C  *Contract
			R  []Result
			F  []Reflection
			RE string
			FE string
		}{c, rs, fs, fmt.Sprint(rerr), fmt.Sprint(ferr)})
		sum := sha256.Sum256(b)
		lines = append(lines, fmt.Sprintf("%s %s leader=%s worker=%s eval=%s pinned=%s hash=%s", id, hex.EncodeToString(sum[:8]), c.Leader, c.Worker, c.Evaluator.Handle, c.Evaluator.PinnedAt, c.Evaluator.Hash))
	}
	// dry-run scrub of every mission file and the trace
	var rels []string
	root := filepath.Join(data, ".punt-labs", "ethos")
	_ = filepath.Walk(filepath.Join(root, "missions"), func(p string, info os.FileInfo, err error) error {
		if err == nil && !info.IsDir() {
			rel, _ := filepath.Rel(data, p)
			rels = append(rels, rel)
		}
		return nil
	})
	rels = append(rels, filepath.Join(".punt-labs", "ethos", "missions.jsonl"))
	res, err := ScrubFiles(data, global, rels, true)
	lines = append(lines, fmt.Sprintf("SCRUB err=%v changed=%d skipped=%d", err, len(res.Changed), len(res.Skipped)))
	for _, c := range res.Changed {
		lines = append(lines, "SCRUB-CHANGED "+c)
	}
	lines = append(lines, fmt.Sprintf("TOTAL %d loadfail %d", len(ids), fails))
	if err := os.WriteFile(out, []byte(strings.Join(lines, "\n")+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}
}

