func TestCreate_RefusesAnAmbiguousRequireRead(t *testing.T) {
	t.Setenv("HOME", t.TempDir())
	s := NewStoreWithRoots(t.TempDir(), t.TempDir())

	err := s.Create(contractRequiringRead("m-2026-08-06-170", "cache/-~-project/config.json"))
	require.Error(t, err)
