					pre, note = red, "held a credential, an address or a path the content pass rewrites"
				}
			}
		}
		out, rule, marker := guardAuditLineFull(pre)
		if marker {
			return out, rule, marker
		}
		return out, joinRules(note, rule), false
	}
}
