// bestPlanKeysTime returns the fastest of three runs of PlanKeys over keys.
func bestPlanKeysTime(keys []string) time.Duration {
	best := time.Duration(math.MaxInt64)
	for range 3 {
		start := time.Now()
		PlanKeys(keys, func(string) string { return "x" }, true)
